var BRAND_MARK = '<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><defs><linearGradient id="afg" x1="3" y1="3" x2="29" y2="29" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#ec4899"/><stop offset=".55" stop-color="#9333ea"/><stop offset="1" stop-color="#3b82f6"/></linearGradient><linearGradient id="afs" x1="6" y1="2" x2="26" y2="18" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#fff" stop-opacity=".26"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient></defs><rect x="3" y="3" width="26" height="26" rx="8" fill="url(#afg)"/><rect x="3" y="3" width="26" height="26" rx="8" fill="url(#afs)"/><path d="M12.6 9.9a1.15 1.15 0 0 1 1.77-.98l8.62 5.6a1.36 1.36 0 0 1 0 2.29l-8.62 5.6a1.15 1.15 0 0 1-1.77-.98Z" fill="#fff"/></svg>';
