    code: "const ProgressChart = ({item}) => {\n  const frame = useCurrentFrame();\n  const {fps} = useVideoConfig();\n\n  const props = item.props || {};\n  const titleText = props.titleText || 'CATALOG ORDER VOLUME';\n  const subtitleText = props.subtitleText || 'Order Share Across Product Categories';\n  const bgGradientStart = props.bgGradientStart || '#2f5044';\n  const bgGradientEnd = props.bgGradientEnd || '#465c54';\n  const barColor = props.barColor || '#ffffff';\n  const trackColor = props.trackColor || 'rgba(255, 255, 255, 0.15)';\n  const textColor = props.textColor || '#ffffff';\n  const fontFamily = props.fontFamily || 'Inter, sans-serif';\n  const monoFont = '\"IBM Plex Mono\", monospace';\n\n  const chartData = [\n    { label: props.label1 || 'Furniture', value: props.val1 ?? 78 },\n    { label: props.label2 || 'Lighting', value: props.val2 ?? 45 },\n    { label: props.label3 || 'Textiles', value: props.val3 ?? 62 },\n    { label: props.label4 || 'Decor', value: props.val4 ?? 53 },\n    { label: props.label5 || 'Storage', value: props.val5 ?? 31 },\n    { label: props.label6 || 'Rugs', value: props.val6 ?? 24 },\n  ];\n\n  const DESIGN_WIDTH = 1920;\n  const DESIGN_HEIGHT = 1080;\n  const scale = Math.min(\n    (item?.width || DESIGN_WIDTH) / DESIGN_WIDTH,\n    (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT\n  );\n\n  const safeFps = fps || 30;\n\n  const rootStyle = {\n    position: 'absolute',\n    top: 0,\n    left: 0,\n    width: DESIGN_WIDTH,\n    height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`,\n    transformOrigin: 'top left',\n    background: `linear-gradient(135deg, ${bgGradientStart}, ${bgGradientEnd})`,\n    fontFamily,\n    display: 'flex',\n    flexDirection: 'column',\n    justifyContent: 'center',\n    padding: '0 160px',\n    boxSizing: 'border-box',\n    overflow: 'hidden',\n  };\n\n  const titleOpacity = interpolate(frame, [5, 25], [0, 1], {extrapolateRight: 'clamp'});\n  const titleY = interpolate(frame, [5, 25], [30, 0], {extrapolateRight: 'clamp', easing: Easing.out(Easing.cubic)});\n\n  const subtitleOpacity = interpolate(frame, [15, 35], [0, 1], {extrapolateRight: 'clamp'});\n  const subtitleY = interpolate(frame, [15, 35], [20, 0], {extrapolateRight: 'clamp', easing: Easing.out(Easing.cubic)});\n\n  return (\n    <div style={rootStyle}>\n      <div style={{ transform: `translateY(${titleY}px)`, opacity: titleOpacity, marginBottom: 12 }}>\n        <h1 style={{ margin: 0, fontSize: 56, color: textColor, fontWeight: 600, letterSpacing: '4px', textTransform: 'uppercase' }}>\n          {titleText}\n        </h1>\n      </div>\n      <div style={{ transform: `translateY(${subtitleY}px)`, opacity: subtitleOpacity, marginBottom: 80 }}>\n        <h2 style={{ margin: 0, fontSize: 24, color: textColor, opacity: 0.7, fontWeight: 300, letterSpacing: '1px' }}>\n          {subtitleText}\n        </h2>\n      </div>\n\n      <div style={{ display: 'flex', flexDirection: 'column', gap: 36, paddingRight: 80 }}>\n        {chartData.map((d, i) => {\n          const delay = 30 + i * 8;\n          const rowOpacity = interpolate(frame, [delay, delay + 15], [0, 1], {extrapolateRight: 'clamp'});\n          const rowY = interpolate(frame, [delay, delay + 15], [20, 0], {extrapolateRight: 'clamp', easing: Easing.out(Easing.cubic)});\n\n          const barProgress = spring({\n            frame: Math.max(0, frame - delay - 5),\n            fps: safeFps,\n            config: { damping: 15, stiffness: 50 }\n          });\n          const currentVal = barProgress * d.value;\n\n          return (\n            <div key={i} style={{ display: 'flex', alignItems: 'center', opacity: rowOpacity, transform: `translateY(${rowY}px)` }}>\n              <div style={{\n                width: 300,\n                textAlign: 'right',\n                paddingRight: 40,\n                fontSize: 20,\n                color: textColor,\n                fontWeight: 300,\n                letterSpacing: '0.02em'\n              }}>\n                {d.label}\n              </div>\n              <div style={{ \n                flex: 1, \n                height: 14, \n                backgroundColor: trackColor, \n                position: 'relative', \n                borderRadius: 2 \n              }}>\n                <div style={{ \n                  position: 'absolute', \n                  top: 0, \n                  left: 0, \n                  bottom: 0, \n                  width: `${currentVal}%`, \n                  backgroundColor: barColor, \n                  borderRadius: 2 \n                }} />\n                <div style={{\n                  position: 'absolute',\n                  left: `${currentVal}%`,\n                  top: '50%',\n                  transform: 'translateY(-50%)',\n                  paddingLeft: 24,\n                  fontSize: 24,\n                  color: textColor,\n                  fontWeight: 500,\n                  fontFamily: monoFont,\n                }}>\n                  {Math.round(currentVal)}%\n                </div>\n              </div>\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n};"
