  const CHART_ZONE_MID_Y = (TITLE_ZONE_H + LEGEND_ZONE_TOP) / 2; // 540

  // Radar: center in chart zone, radius stays clear of zone boundaries
  const cx = 960;
  const cy = CHART_ZONE_MID_Y; // 540
