  const safeFps = fps || 30;
  const safeSpring = (delay = 0, config = { damping: 15 }) => {
    return spring({ frame: Math.max(0, frame - delay), fps: safeFps, config });
  };

  const cardSpring = safeSpring(5, { damping: 14, mass: 1.2 });
  const contentSpring = safeSpring(15, { damping: 16 });
  const areaSpring = safeSpring(20, { damping: 18, mass: 1.5 });

