    code: `const SalesTrendChart = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const props = item.props || {};
  const titleText = props.titleText || 'Listener Growth';
  const kpi1Value = props.kpi1Value || '38%';
  const kpi1Label = props.kpi1Label || 'stream count';
  const kpi1Color = props.kpi1Color || '#42c36a';
  const kpi2Value = props.kpi2Value || '12%';
  const kpi2Label = props.kpi2Label || 'download count';
  const kpi2Color = props.kpi2Color || '#907800';
  const backgroundColor = props.backgroundColor || '#E8E6F0';
  const cardColor = props.cardColor || '#FFFFFF';

  const DESIGN_WIDTH = 1920;
  const DESIGN_HEIGHT = 1080;
  const scale = Math.min(
    (item?.width || DESIGN_WIDTH) / DESIGN_WIDTH,
    (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT
  );

  const springConfig = { damping: 20, stiffness: 100, mass: 0.8 };
  const slowSpringConfig = { damping: 100, stiffness: 30, mass: 1 };

  const cardEntrance = spring({ frame: Math.max(0, frame), fps, config: springConfig });
  const contentEntrance = spring({ frame: Math.max(0, frame - 15), fps, config: springConfig });
  const lineProgress = spring({ frame: Math.max(0, frame - 25), fps, config: slowSpringConfig });

  const months = ['January', 'February', 'March', 'April', 'May', 'June'];
  const dataGreen = [15, 22, 28, 30, 36, 40];
  const dataPurple = [5, 8, 5, 6, 7, 8];

  // Chart sizing
  // yLabelX: where Y-axis "0%/25%..." labels sit (textAnchor end)
  // plotLeft: where the plot area and first data point start \u2014 must be clearly to the right of yLabelX
  // padX: symmetric right-side padding so last dot doesn't clip
  const yLabelX = 0;       // Y labels end here
  const plotLeft = 80;     // plot starts here \u2014 80px gap from Y labels
  const padX = 40;         // right-side padding
  const plotWidth = 900 - plotLeft - padX; // remaining width for the lines
  const chartHeight = 320;
  const getX = (index) => plotLeft + (index / (months.length - 1)) * plotWidth;
  const getY = (val) => chartHeight - (val / 100) * chartHeight;

  const createPath = (data) => {
    return data.map((val, i) => {
      const x = getX(i);
      const y = getY(val);
      return \`\${i === 0 ? 'M' : 'L'} \${x} \${y}\`;
    }).join(' ');
  };

  const pathGreen = createPath(dataGreen);
  const pathPurple = createPath(dataPurple);
  const pathLength = 1200;

  const rootStyle = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: DESIGN_WIDTH,
    height: DESIGN_HEIGHT,
    backgroundColor: backgroundColor,
    transform: \`scale(\${scale})\`,
    transformOrigin: 'top left',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontFamily: 'Inter, sans-serif',
    overflow: 'hidden',
  };

  const cardStyle = {
    width: 1400,
    height: 800,
    backgroundColor: cardColor,
    borderRadius: 40,
    boxShadow: '0 30px 80px rgba(0,0,0,0.08)',
    padding: '80px 100px',
    position: 'relative',
    display: 'flex',
    flexDirection: 'column',
    opacity: cardEntrance,
    transform: \`translateY(\${(1 - cardEntrance) * 40}px) scale(\${0.95 + 0.05 * cardEntrance})\`,
    overflow: 'hidden',
  };

  const headerRowStyle = {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    marginBottom: 40,
    opacity: contentEntrance,
    transform: \`translateX(\${(1 - contentEntrance) * -20}px)\`,
  };

  const titleStyle = {
    fontSize: 56,
    fontWeight: 700,
    color: '#333333',
    margin: 0,
    letterSpacing: '-0.02em',
  };

  const kpiGroupStyle = {
    display: 'flex',
    gap: 80,
  };

  const kpiItemStyle = {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'flex-end',
  };

  const kpiValueStyle = (color) => ({
    fontSize: 64,
    fontWeight: 800,
    color: color,
    lineHeight: 1,
    marginBottom: 8,
  });

  const kpiLabelStyle = {
    fontSize: 18,
    fontWeight: 600,
    color: '#9E9E9E',
    textTransform: 'uppercase',
    letterSpacing: '0.05em',
  };

  const DnaWatermark = () => {
    const rungs = 8;
    return (
      <div style={{
        position: 'absolute',
        right: -100,
        top: '20%',
        width: 400,
        height: 600,
        opacity: 0.06,
        transform: 'rotate(-15deg)',
        pointerEvents: 'none',
      }}>
        <svg width="100%" height="100%" viewBox="0 0 200 600">
          <path d="M 60,0 Q 140,75 60,150 T 60,300 T 60,450" fill="none" stroke="#000" strokeWidth="8" />
          <path d="M 140,0 Q 60,75 140,150 T 140,300 T 140,450" fill="none" stroke="#000" strokeWidth="8" />
          {new Array(rungs).fill(0).map((_, i) => (
            <line key={i} x1="60" y1={30 + i * 60} x2="140" y2={30 + i * 60} stroke="#000" strokeWidth="6" strokeLinecap="round" />
          ))}
        </svg>
      </div>
    );
  };

  // viewBox: starts 20px left of yLabelX(0), ends 20px right of plotLeft+plotWidth+padX(900)
  const vbLeft = -20;
  const vbTop = -20;
  const vbWidth = 940;  // 20 left margin + 900 + 20 right margin
  const vbHeight = chartHeight + 80;

  return (
    <div style={rootStyle}>
      <div style={cardStyle}>
        <DnaWatermark />

        <div style={headerRowStyle}>
          <h1 style={titleStyle}>{titleText}</h1>
          <div style={kpiGroupStyle}>
            <div style={kpiItemStyle}>
              <span style={kpiValueStyle(kpi1Color)}>{kpi1Value}</span>
              <span style={kpiLabelStyle}>{kpi1Label}</span>
            </div>
            <div style={kpiItemStyle}>
              <span style={kpiValueStyle(kpi2Color)}>{kpi2Value}</span>
              <span style={kpiLabelStyle}>{kpi2Label}</span>
            </div>
          </div>
        </div>

        {/* Chart container \u2014 flex:1 fills remaining card space after header */}
        <div style={{ position: 'relative', flex: 1, minHeight: 0 }}>
          <svg
            width="100%"
            height="100%"
            viewBox={\`\${vbLeft} \${vbTop} \${vbWidth} \${vbHeight}\`}
            preserveAspectRatio="xMidYMid meet"
          >
            {/* Grid & Y-Labels */}
            {[0, 25, 50, 75, 100].map((tick) => (
              <g key={tick} opacity={contentEntrance}>
                <line
                  x1={plotLeft} y1={getY(tick)}
                  x2={plotLeft + plotWidth} y2={getY(tick)}
                  stroke="#EEEEEE"
                  strokeWidth="2"
                  strokeDasharray="6,6"
                />
                <text
                  x={yLabelX} y={getY(tick) + 6}
                  textAnchor="end"
                  fill="#B0B0B0"
                  fontSize="16"
                  fontWeight="500"
                >
                  {tick}%
                </text>
              </g>
            ))}

            {/* X-Labels */}
            {months.map((m, i) => (
              <text
                key={m}
                x={getX(i)} y={chartHeight + 36}
                textAnchor="middle"
                fill="#909090"
                fontSize="16"
                fontWeight="600"
                opacity={contentEntrance}
              >
                {m}
              </text>
            ))}

            {/* Lines */}
            <path
              d={pathGreen}
              fill="none"
              stroke={kpi1Color}
              strokeWidth="6"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray={pathLength}
              strokeDashoffset={pathLength * (1 - Math.min(1, lineProgress * 1.5))}
            />
            <path
              d={pathPurple}
              fill="none"
              stroke={kpi2Color}
              strokeWidth="6"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray={pathLength}
              strokeDashoffset={pathLength * (1 - Math.min(1, lineProgress * 1.5))}
            />

            {/* Dots Green */}
            {dataGreen.map((val, i) => {
              const cx = getX(i);
              const cy = getY(val);
              const dotScale = spring({
                frame: Math.max(0, frame - 30 - i * 5),
                fps,
                config: { damping: 15, stiffness: 200 },
              });
              return (
                <circle
                  key={\`g-\${i}\`}
                  cx={cx} cy={cy} r={8}
                  fill="#FFFFFF"
                  stroke={kpi1Color}
                  strokeWidth="5"
                  style={{ transformOrigin: \`\${cx}px \${cy}px\`, transform: \`scale(\${dotScale})\` }}
                />
              );
            })}

            {/* Dots Purple */}
            {dataPurple.map((val, i) => {
              const cx = getX(i);
              const cy = getY(val);
              const dotScale = spring({
                frame: Math.max(0, frame - 30 - i * 5),
                fps,
                config: { damping: 15, stiffness: 200 },
              });
              return (
                <circle
                  key={\`p-\${i}\`}
                  cx={cx} cy={cy} r={8}
                  fill="#FFFFFF"
                  stroke={kpi2Color}
                  strokeWidth="5"
                  style={{ transformOrigin: \`\${cx}px \${cy}px\`, transform: \`scale(\${dotScale})\` }}
                />
              );
            })}
          </svg>
        </div>
      </div>
    </div>
  );
};
`
