    code: "const RevenueOverlay = ({item}) => {\n  const frame = useCurrentFrame();\n  const {fps, durationInFrames} = useVideoConfig();\n\n  const props = item.props || {};\n  const titleText = props.titleText;\n  const prefix = props.prefix;\n  const targetValue = props.targetValue;\n  const titleColor = props.titleColor;\n  const numberColor = props.numberColor;\n  const transparentBackground = props.transparentBackground;\n  const fontFamily = props.fontFamily;\n\n  const DESIGN_WIDTH = 1920;\n  const DESIGN_HEIGHT = 1080;\n  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);\n\n  // Timings: 0-24 (Title fade), 30-54 (Number fade), 30-105 (Number roll)\n  const titleOpacity = interpolate(frame, [0, 24], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });\n  const titleBlur = interpolate(frame, [0, 24], [24, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });\n\n  const numberOpacity = interpolate(frame, [30, 54], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });\n  const numberBlur = interpolate(frame, [30, 54], [40, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });\n\n  const countProgress = interpolate(frame, [30, 105], [0, 1], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n    easing: Easing.bezier(0.1, 1, 0.2, 1) // Decelerates smoothly near the target\n  });\n  const currentValue = Math.floor(countProgress * Number(targetValue));\n  const formattedValue = `${prefix}${currentValue.toLocaleString('en-US')}`;\n\n  const rootStyle = {\n    position: 'absolute',\n    top: 0,\n    left: 0,\n    width: DESIGN_WIDTH,\n    height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`,\n    transformOrigin: 'top left',\n    backgroundColor: transparentBackground ? 'transparent' : '#000708',\n    display: 'flex',\n    flexDirection: 'column',\n    justifyContent: 'center',\n    alignItems: 'center',\n    fontFamily: fontFamily\n  };\n\n  const titleStyle = {\n    fontSize: '72px',\n    fontWeight: 600,\n    color: titleColor,\n    opacity: titleOpacity,\n    filter: `blur(${titleBlur}px)`,\n    textShadow: `0 0 15px ${titleColor}80, 0 0 30px ${titleColor}40`,\n    margin: 0,\n    marginBottom: '20px',\n    lineHeight: 1,\n    letterSpacing: '1px',\n    textAlign: 'center'\n  };\n\n  const numberStyle = {\n    fontSize: '300px',\n    fontWeight: 800,\n    color: numberColor,\n    opacity: numberOpacity,\n    filter: `blur(${numberBlur}px)`,\n    textShadow: `0 0 40px ${numberColor}, 0 0 80px ${numberColor}B3, 0 0 140px ${numberColor}80`,\n    margin: 0,\n    lineHeight: 1,\n    letterSpacing: '-6px',\n    textAlign: 'center',\n    marginTop: '-20px'\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={titleStyle}>{titleText}</div>\n      <div style={numberStyle}>{formattedValue}</div>\n    </div>\n  );\n};"
