    code: "const RevenueCounter = ({item}) => {\n  const frame = useCurrentFrame();\n  const {fps} = useVideoConfig();\n  \n  const props = item.props || {};\n  const targetRevenue = props.targetRevenue ?? 1234567;\n  const labelText = props.labelText || 'MEMBERS THIS QUARTER';\n  const currencySymbol = props.currencySymbol || '$';\n  const bgColor = props.bgColor || '#17162d';\n  const boxColor = props.boxColor || 'rgba(255, 255, 255, 0.1)';\n  const boxBorderColor = props.boxBorderColor || 'rgba(255, 255, 255, 0.2)';\n  const numberColor = props.numberColor || '#FFFFFF';\n  const labelBgColor = props.labelBgColor || '#f48ddf';\n  const labelTextColor = props.labelTextColor || '#17162d';\n  const circleColor = props.circleColor || '#9d81f7';\n  const arcColor = props.arcColor || '#abe0ff';\n  const cornerColor = props.cornerColor || '#a47322';\n  const fontFamily = props.fontFamily || 'Inter, sans-serif';\n\n  const DESIGN_WIDTH = 1920;\n  const DESIGN_HEIGHT = 1080;\n  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);\n\n  const safeFps = fps || 30;\n  const safeSpring = (delay = 0, config = { damping: 12, mass: 0.8, stiffness: 120 }) => {\n    return spring({ frame: Math.max(0, frame - delay), fps: safeFps, config });\n  };\n\n  const bgScale = safeSpring(0, { damping: 20 });\n  const circleScale = safeSpring(5);\n  const arcScale = safeSpring(10);\n  const cornerScale = safeSpring(15);\n  const boxScale = safeSpring(20, { damping: 15, mass: 1 });\n  const labelScale = safeSpring(30, { damping: 12 });\n\n  const countProgress = interpolate(frame, [25, 100], [0, 1], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n    easing: Easing.out(Easing.cubic)\n  });\n  \n  const currentNumber = Math.floor(countProgress * targetRevenue);\n  const displayNumber = currentNumber.toLocaleString('en-US');\n\n  const rootStyle = {\n    position: 'absolute',\n    top: 0,\n    left: 0,\n    width: DESIGN_WIDTH,\n    height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`,\n    transformOrigin: 'top left',\n    backgroundColor: bgColor,\n    overflow: 'hidden',\n    fontFamily: fontFamily,\n    display: 'flex',\n    justifyContent: 'center',\n    alignItems: 'center',\n    opacity: bgScale\n  };\n\n  const circleStyle = {\n    position: 'absolute',\n    top: -200,\n    right: -150,\n    width: 800,\n    height: 800,\n    borderRadius: '50%',\n    backgroundColor: circleColor,\n    transform: `scale(${circleScale})`,\n    transformOrigin: 'center center'\n  };\n\n  const arcStyle = {\n    position: 'absolute',\n    top: 150,\n    left: 150,\n    width: 400,\n    height: 400,\n    borderRadius: '50%',\n    border: `60px solid ${arcColor}`,\n    borderBottomColor: 'transparent',\n    borderLeftColor: 'transparent',\n    transform: `scale(${arcScale}) rotate(-20deg)`,\n    transformOrigin: 'center center'\n  };\n\n  const cornerStyle = {\n    position: 'absolute',\n    bottom: -250,\n    left: -200,\n    width: 600,\n    height: 600,\n    backgroundColor: cornerColor,\n    transform: `scale(${cornerScale}) rotate(45deg)`,\n    transformOrigin: 'center center',\n    borderRadius: 80\n  };\n\n  const pillStyle = {\n    position: 'absolute',\n    bottom: 250,\n    right: 250,\n    width: 180,\n    height: 60,\n    backgroundColor: labelBgColor,\n    borderRadius: 30,\n    transform: `scale(${safeSpring(20)}) rotate(-15deg)`,\n    transformOrigin: 'center center'\n  };\n\n  const boxWrapperStyle = {\n    position: 'relative',\n    transform: `scale(${boxScale})`,\n    display: 'flex',\n    flexDirection: 'column',\n    alignItems: 'center'\n  };\n\n  const boxStyle = {\n    width: 1100,\n    height: 450,\n    backgroundColor: boxColor,\n    border: `4px solid ${boxBorderColor}`,\n    borderRadius: 40,\n    display: 'flex',\n    justifyContent: 'center',\n    alignItems: 'center',\n    boxShadow: '0 30px 60px rgba(0,0,0,0.3)',\n    backdropFilter: 'blur(10px)'\n  };\n\n  const contentStyle = {\n    display: 'flex',\n    alignItems: 'baseline',\n    gap: 30\n  };\n\n  const currencyStyle = {\n    fontSize: 120,\n    fontWeight: 700,\n    color: numberColor,\n    opacity: 0.8\n  };\n\n  const numberStyle = {\n    fontSize: 180,\n    fontWeight: 900,\n    color: numberColor,\n    letterSpacing: '-2px'\n  };\n\n  const labelStyle = {\n    position: 'absolute',\n    bottom: -40,\n    backgroundColor: labelBgColor,\n    color: labelTextColor,\n    padding: '25px 60px',\n    borderRadius: 100,\n    fontSize: 42,\n    fontWeight: 800,\n    letterSpacing: 4,\n    textTransform: 'uppercase',\n    boxShadow: '0 15px 30px rgba(0,0,0,0.2)',\n    transform: `scale(${labelScale})`,\n    transformOrigin: 'center center'\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={circleStyle} />\n      <div style={arcStyle} />\n      <div style={cornerStyle} />\n      <div style={pillStyle} />\n      \n      <div style={boxWrapperStyle}>\n        <div style={boxStyle}>\n          <div style={contentStyle}>\n            <span style={currencyStyle}>{currencySymbol}</span>\n            <span style={numberStyle}>{displayNumber}</span>\n          </div>\n        </div>\n        <div style={labelStyle}>\n          {labelText}\n        </div>\n      </div>\n    </div>\n  );\n};"
