    code: "const PixelScoreCard = ({item}) => {\n  const frame = useCurrentFrame();\n  const {fps} = useVideoConfig();\n\n  const props = item.props || {};\n  const headerText = props.headerText || 'MATCH RESULT';\n  const homeScore = props.homeScore || '7';\n  const awayScore = props.awayScore || '3';\n  const homeLabel = props.homeLabel || 'HOST';\n  const awayLabel = props.awayLabel || 'GUEST';\n  const headerColor = props.headerColor || '#8efca8';\n  const cardBgColor = props.cardBgColor || '#FFFFFF';\n  const shadowColor = props.shadowColor || '#000000';\n  const fontFamily = props.fontFamily || '\"Press Start 2P\", \"VT323\", monospace';\n\n  const DESIGN_WIDTH = 500;\n  const DESIGN_HEIGHT = 220;\n  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);\n\n  const safeFps = fps || 30;\n\n  // Elastic pop animation for entrance\n  const pop = spring({\n    frame,\n    fps: safeFps,\n    config: { damping: 10, stiffness: 160, mass: 0.8 }\n  });\n\n  const rootStyle = {\n    position: 'absolute', \n    top: 0, \n    left: 0,\n    width: DESIGN_WIDTH, \n    height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`, \n    transformOrigin: 'top left',\n    backgroundColor: 'transparent',\n    display: 'flex',\n    justifyContent: 'center',\n    alignItems: 'center',\n  };\n\n  const cardStyle = {\n    width: 320,\n    height: 150,\n    backgroundColor: cardBgColor,\n    border: '2px solid #000000',\n    boxShadow: `4px 4px 0px ${shadowColor}, 8px 8px 0px ${shadowColor}88`,\n    display: 'flex',\n    flexDirection: 'column',\n    transform: `scale(${pop})`,\n    overflow: 'hidden',\n    fontFamily: fontFamily,\n  };\n\n  const headerStyle = {\n    height: 36,\n    backgroundColor: headerColor,\n    borderBottom: '2px solid #000000',\n    display: 'flex',\n    justifyContent: 'center',\n    alignItems: 'center',\n    color: '#000000',\n    fontSize: 14,\n    letterSpacing: 2,\n    textShadow: '1px 1px 0px rgba(255,255,255,0.5)',\n  };\n\n  const bodyStyle = {\n    flex: 1,\n    display: 'flex',\n    flexDirection: 'row',\n    justifyContent: 'center',\n    alignItems: 'center',\n    padding: '10px 20px',\n    gap: 30,\n  };\n\n  const scoreBlockStyle = {\n    display: 'flex',\n    flexDirection: 'column',\n    alignItems: 'center',\n    justifyContent: 'center',\n    gap: 12,\n    width: 80,\n  };\n\n  const numberStyle = {\n    fontSize: 48,\n    color: '#000000',\n    lineHeight: 1,\n    textShadow: '2px 2px 0px rgba(0,0,0,0.1)',\n  };\n\n  const labelStyle = {\n    fontSize: 12,\n    color: '#000000',\n    letterSpacing: 1,\n  };\n\n  const colonStyle = {\n    fontSize: 40,\n    color: '#000000',\n    lineHeight: 1,\n    marginTop: -20,\n    textShadow: '2px 2px 0px rgba(0,0,0,0.1)',\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={cardStyle}>\n        <div style={headerStyle}>{headerText}</div>\n        <div style={bodyStyle}>\n          <div style={scoreBlockStyle}>\n            <div style={numberStyle}>{homeScore}</div>\n            <div style={labelStyle}>{homeLabel}</div>\n          </div>\n          <div style={colonStyle}>:</div>\n          <div style={scoreBlockStyle}>\n            <div style={numberStyle}>{awayScore}</div>\n            <div style={labelStyle}>{awayLabel}</div>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n};"
