    code: "const RetroTipCard = ({item}) => {\n  const frame = useCurrentFrame();\n  const {fps} = useVideoConfig();\n\n  const props = item.props || {};\n  const headerText = props.headerText || '4 TIPS FOR BETTER PODCASTS';\n  const tip1 = props.tip1 || '1. Script your intro';\n  const tip2 = props.tip2 || '2. Mic close, room quiet';\n  const tip3 = props.tip3 || '3. Trim the pauses';\n\n  const headerColor = props.headerColor || '#bee6ff';\n  const cardBgColor = props.cardBgColor || '#FFFFFF';\n  const textColor = props.textColor || '#000000';\n\n  const headerFontFamily = props.headerFontFamily || '\"Press Start 2P\", system-ui';\n  const bodyFontFamily = props.bodyFontFamily || '\"VT323\", monospace';\n\n  const DESIGN_WIDTH = 680;\n  const DESIGN_HEIGHT = 300;\n  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);\n\n  const safeFps = fps || 30;\n  const safeSpring = (delay = 0, config = { damping: 14, stiffness: 100 }) => {\n    return spring({ frame: Math.max(0, frame - delay), fps: safeFps, config });\n  };\n\n  // Card Entrance\n  const cardScaleProg = safeSpring(5, { damping: 12, stiffness: 90 });\n  const cardScale = interpolate(cardScaleProg, [0, 1], [0.8, 1]);\n  const cardRotate = interpolate(cardScaleProg, [0, 1], [-4, 0]);\n  const cardOpacity = Math.min(1, Math.max(0, cardScaleProg * 2));\n\n  // Tip Entrances\n  const tipSpringConfig = { damping: 15, stiffness: 120 };\n  const tip1Prog = safeSpring(15, tipSpringConfig);\n  const tip2Prog = safeSpring(25, tipSpringConfig);\n  const tip3Prog = safeSpring(35, tipSpringConfig);\n\n  const tip1Opacity = Math.min(1, Math.max(0, tip1Prog * 1.5));\n  const tip1X = interpolate(tip1Prog, [0, 1], [-20, 0]);\n\n  const tip2Opacity = Math.min(1, Math.max(0, tip2Prog * 1.5));\n  const tip2X = interpolate(tip2Prog, [0, 1], [-20, 0]);\n\n  const tip3Opacity = Math.min(1, Math.max(0, tip3Prog * 1.5));\n  const tip3X = interpolate(tip3Prog, [0, 1], [-20, 0]);\n\n  const rootStyle = {\n    position: 'absolute', top: 0, left: 0,\n    width: DESIGN_WIDTH, height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`, transformOrigin: 'top left',\n    backgroundColor: 'transparent',\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    overflow: 'hidden'\n  };\n\n  const cardStyle = {\n    width: 520,\n    height: 220,\n    backgroundColor: cardBgColor,\n    border: `4px solid ${textColor}`,\n    boxShadow: `8px 8px 0px ${textColor}`,\n    display: 'flex',\n    flexDirection: 'column',\n    transform: `scale(${cardScale}) rotate(${cardRotate}deg)`,\n    opacity: cardOpacity,\n    transformOrigin: 'center center'\n  };\n\n  const headerStyle = {\n    height: 44,\n    backgroundColor: headerColor,\n    borderBottom: `4px solid ${textColor}`,\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    paddingLeft: 16\n  };\n\n  const headerTextStyle = {\n    fontFamily: headerFontFamily,\n    fontSize: 14,\n    color: textColor,\n    fontWeight: 'bold',\n    marginTop: 4,\n    letterSpacing: '1px'\n  };\n\n  const windowControlsStyle = {\n    width: 44,\n    height: '100%',\n    borderLeft: `4px solid ${textColor}`,\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    fontFamily: headerFontFamily,\n    fontSize: 16,\n    color: textColor,\n    fontWeight: 'bold',\n    backgroundColor: 'rgba(255,255,255,0.2)',\n    cursor: 'pointer'\n  };\n\n  const bodyStyle = {\n    flex: 1,\n    padding: '24px 32px',\n    display: 'flex',\n    flexDirection: 'column',\n    justifyContent: 'center',\n    gap: '20px'\n  };\n\n  const tipBaseStyle = {\n    fontFamily: bodyFontFamily,\n    fontSize: 26,\n    color: textColor,\n    margin: 0,\n    textShadow: `2px 2px 0px rgba(0,0,0,0.15)`\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={cardStyle}>\n        <div style={headerStyle}>\n          <div style={headerTextStyle}>{headerText}</div>\n          <div style={windowControlsStyle}>X</div>\n        </div>\n        <div style={bodyStyle}>\n          <div style={{ ...tipBaseStyle, opacity: tip1Opacity, transform: `translateX(${tip1X}px)` }}>\n            {tip1}\n          </div>\n          <div style={{ ...tipBaseStyle, opacity: tip2Opacity, transform: `translateX(${tip2X}px)` }}>\n            {tip2}\n          </div>\n          <div style={{ ...tipBaseStyle, opacity: tip3Opacity, transform: `translateX(${tip3X}px)` }}>\n            {tip3}\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n};"
