    thumb: "/thumbnails/a8881761-23dc-4cb7-ac6e-11aa29aa6df7.jpg",
    code: `const EditorialNameCard = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const props = item.props || {};
  const firstName = props.firstName;
  const lastName = props.lastName;
  const role = props.role;
  const bgColor = props.bgColor;
  const textColor = props.textColor;
  const lineColor = props.lineColor;

  const DESIGN_WIDTH = 1920;
  const DESIGN_HEIGHT = 1080;
  const scale = Math.min(
    (item?.width || DESIGN_WIDTH) / DESIGN_WIDTH,
    (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT
  );

  const safeFps = fps || 30;
  const cardHeight = 380;

  // \u2500\u2500 Exit \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  const exitDuration = 24;
  const exitStart = durationInFrames - exitDuration;
  const isExiting = frame >= exitStart;
  const exitT = isExiting
    ? interpolate(frame, [exitStart, durationInFrames - 1], [0, 1], { extrapolateRight: 'clamp' })
    : 0;
  const exitEased = Easing.in(Easing.cubic)(exitT);
  const exitSlide = interpolate(exitEased, [0, 1], [0, cardHeight + 20]);

  // \u2500\u2500 Entrance: card slides up \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  const cardEnter = spring({
    frame,
    fps: safeFps,
    config: { damping: 22, stiffness: 100, mass: 0.8 },
  });
  const cardSlideIn = interpolate(cardEnter, [0, 1], [cardHeight, 0]);
  const cardTranslateY = isExiting ? exitSlide : cardSlideIn;

  // \u2500\u2500 Text: fade only, no translateY \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  const fadeIn = (delay) =>
    interpolate(frame, [delay, delay + 10], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const name1Op   = isExiting ? interpolate(exitEased, [0, 0.4], [1, 0]) : fadeIn(14);
  const name2Op   = isExiting ? interpolate(exitEased, [0, 0.4], [1, 0]) : fadeIn(20);
  const lineWidth = isExiting
    ? interpolate(exitEased, [0, 0.6], [150, 0])
    : interpolate(
        spring({ frame: Math.max(0, frame - 26), fps: safeFps, config: { damping: 30, stiffness: 100, mass: 0.8 } }),
        [0, 1], [0, 150]
      );
  const titleOp = isExiting ? interpolate(exitEased, [0, 0.3], [1, 0]) : fadeIn(32);
  const ghostOp = isExiting ? interpolate(exitEased, [0, 1], [0.15, 0]) : interpolate(cardEnter, [0, 1], [0, 0.15]);

  const gpuText = {
    transform: 'translateZ(0)',
    WebkitFontSmoothing: 'antialiased',
    backfaceVisibility: 'hidden',
  };

  const rootStyle = {
    position: 'absolute',
    top: 0, left: 0,
    width: DESIGN_WIDTH,
    height: DESIGN_HEIGHT,
    transform: \`scale(\${scale})\`,
    transformOrigin: 'top left',
    overflow: 'hidden',
    fontFamily: 'serif',
  };

  const cardStyle = {
    position: 'absolute',
    bottom: 0, left: 0,
    width: '100%',
    height: cardHeight,
    backgroundColor: bgColor,
    transform: \`translateY(\${cardTranslateY}px)\`,
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'center',
    padding: '0 120px',
    boxSizing: 'border-box',
    overflow: 'hidden',
    willChange: 'transform',
  };

  const contentContainer = {
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'center',
    zIndex: 2,
    width: '100%',
  };

  const nameBlock = {
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
  };

  const firstNameStyle = {
    ...gpuText,
    fontSize: '120px',
    fontWeight: '800',
    lineHeight: '0.9',
    color: textColor,
    textTransform: 'uppercase',
    opacity: name1Op,
  };

  const lastNameStyle = {
    ...gpuText,
    fontSize: '60px',
    fontWeight: '400',
    color: textColor,
    marginTop: '10px',
    letterSpacing: '2px',
    textTransform: 'uppercase',
    opacity: name2Op,
  };

  const separatorStyle = {
    height: '2px',
    backgroundColor: lineColor,
    width: lineWidth,
    margin: '0 50px',
    marginTop: '40px',
    alignSelf: 'flex-start',
    flexShrink: 0,
  };

  const titleStyle = {
    ...gpuText,
    fontSize: '32px',
    fontStyle: 'italic',
    color: textColor,
    opacity: titleOp,
    marginTop: '25px',
    alignSelf: 'flex-start',
    whiteSpace: 'nowrap',
  };

  const ghostStyle = {
    position: 'absolute',
    right: '-50px',
    bottom: '-100px',
    width: '800px',
    height: '800px',
    opacity: ghostOp,
    zIndex: 1,
    pointerEvents: 'none',
  };

  return (
    <div style={rootStyle}>
      <div style={cardStyle}>
        <div style={ghostStyle}>
          <svg viewBox="0 0 200 200" width="100%" height="100%">
            <path
              fill={textColor}
              d="M100,130 C130,130 150,160 160,200 L40,200 C50,160 70,130 100,130 M100,50 C125,50 140,80 130,110 C120,130 80,130 70,110 C60,80 75,50 100,50 Z"
            />
          </svg>
        </div>
        <div style={contentContainer}>
          <div style={nameBlock}>
            <div style={firstNameStyle}>{firstName}</div>
            <div style={lastNameStyle}>{lastName}</div>
          </div>
          <div style={separatorStyle} />
          <div style={titleStyle}>{role}</div>
        </div>
      </div>
    </div>
  );
};`
