    code: "const HandDrawnLowerThird = ({item}) => {\n  const frame = useCurrentFrame();\n  const { fps, durationInFrames } = useVideoConfig();\n  \n  const props = item.props || {};\n  const nameText = props.nameText;\n  const titleText = props.titleText;\n  const introText = props.introText;\n  const accentColor = props.accentColor;\n  const textColor = props.textColor;\n\n  const DESIGN_WIDTH = 460;\n  const DESIGN_HEIGHT = 120;\n  const scale = Math.min(\n    (item?.width || DESIGN_WIDTH) / DESIGN_WIDTH,\n    (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT\n  );\n\n  const safeFps = fps || 30;\n  const outDuration = 22;\n  const outStartFrame = durationInFrames - outDuration;\n\n  const slideIn = spring({\n    frame,\n    fps: safeFps,\n    config: { damping: 20, stiffness: 100, mass: 1 },\n    from: -500,\n    to: 40,\n  });\n\n  const outProgress = interpolate(\n    frame,\n    [outStartFrame, outStartFrame + outDuration],\n    [0, 1],\n    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.in(Easing.cubic) }\n  );\n  const slideOut = interpolate(outProgress, [0, 1], [40, -500]);\n  const slideX = frame >= outStartFrame ? slideOut : slideIn;\n\n  const wobbleRotation = Math.sin(frame / 20) * 0.1;\n  const textStartFrame = 20;\n\n  const nameOpacity = interpolate(frame, [textStartFrame, textStartFrame + 15], [0, 1], { extrapolateRight: 'clamp' });\n  const dividerOpacity = interpolate(frame, [textStartFrame + 18, textStartFrame + 28], [0, 1], { extrapolateRight: 'clamp' });\n  const dividerScale = interpolate(frame, [textStartFrame + 18, textStartFrame + 28], [0, 1], { extrapolateRight: 'clamp' });\n  const titleOpacity = interpolate(frame, [textStartFrame + 20, textStartFrame + 35], [0, 1], { extrapolateRight: 'clamp' });\n  const introOpacity = interpolate(frame, [textStartFrame + 35, textStartFrame + 50], [0, 1], { extrapolateRight: 'clamp' });\n\n  const FONT = '\"Shadows Into Light\", cursive';\n\n  const rootStyle = {\n    position: 'absolute',\n    top: 0,\n    left: 0,\n    width: DESIGN_WIDTH,\n    height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`,\n    transformOrigin: 'top left',\n    backgroundColor: 'transparent',\n    fontFamily: FONT,\n    color: textColor,\n  };\n\n  const containerStyle = {\n    position: 'absolute',\n    top: 20,\n    left: slideX,\n    display: 'flex',\n    alignItems: 'center',\n    filter: 'drop-shadow(1px 2px 3px rgba(0,0,0,0.3))',\n    transform: `rotate(${wobbleRotation}deg)`,\n  };\n\n  const STRIP_W = 360;\n  const STRIP_H = 65;\n\n  const stripStyle = {\n    backgroundColor: '#fdfdfd',\n    padding: '10px 24px 10px 40px',\n    borderRadius: '1px',\n    width: STRIP_W + 'px',\n    height: STRIP_H + 'px',\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'flex-start',\n    position: 'relative',\n    zIndex: 1,\n    backgroundImage: 'linear-gradient(178deg, #fff 0%, #f4f4f4 100%)',\n    clipPath: `polygon(8px 0%, ${STRIP_W}px 6px, ${STRIP_W - 8}px ${STRIP_H - 6}px, 0px ${STRIP_H}px)`,\n    boxSizing: 'border-box',\n    overflow: 'hidden',\n  };\n\n  const logoContainerStyle = {\n    position: 'absolute',\n    left: -30,\n    top: 5,\n    width: '60px',\n    height: '55px',\n    backgroundColor: accentColor,\n    zIndex: 2,\n    display: 'flex',\n    justifyContent: 'center',\n    alignItems: 'center',\n    clipPath: 'polygon(20% 0%, 90% 10%, 100% 80%, 80% 100%, 10% 90%, 0% 20%)',\n    transform: 'rotate(-5deg)',\n  };\n\n  const LogoIcon = () => (\n    <svg width=\"30\" height=\"30\" viewBox=\"0 0 100 100\" style={{ fill: textColor }}>\n      <path d=\"M20,20 L40,30 L40,70 L20,80 Z\" />\n      <path d=\"M50,10 L90,50 L50,90 Z\" />\n    </svg>\n  );\n\n  const nameStyle = {\n    fontSize: '22px',\n    fontWeight: 800,\n    marginRight: '10px',\n    letterSpacing: '0px',\n    opacity: nameOpacity,\n    fontFamily: FONT,\n    whiteSpace: 'nowrap',\n    flexShrink: 0,\n  };\n\n  const dividerStyle = {\n    width: '1.5px',\n    height: '30px',\n    backgroundColor: textColor,\n    borderRadius: '1px',\n    marginRight: '10px',\n    flexShrink: 0,\n    transform: `rotate(2deg) scaleY(${dividerScale})`,\n    opacity: dividerOpacity,\n  };\n\n  const infoContainerStyle = {\n    display: 'flex',\n    flexDirection: 'column',\n    justifyContent: 'center',\n    alignItems: 'flex-start',\n    overflow: 'hidden',\n    flexShrink: 1,\n    minWidth: 0,\n  };\n\n  const roleStyle = {\n    fontSize: '13px',\n    fontWeight: 400,\n    fontFamily: FONT,\n    whiteSpace: 'nowrap',\n    height: '16px',\n    lineHeight: '16px',\n    color: textColor,\n    marginBottom: '3px',\n    opacity: titleOpacity,\n  };\n\n  const subStyle = {\n    fontSize: '13px',\n    fontWeight: 400,\n    fontFamily: FONT,\n    whiteSpace: 'nowrap',\n    height: '16px',\n    lineHeight: '16px',\n    color: textColor,\n    opacity: introOpacity,\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={containerStyle}>\n        <div style={logoContainerStyle}>\n          <LogoIcon />\n        </div>\n        <div style={stripStyle}>\n          <div style={nameStyle}>{nameText}</div>\n          <div style={dividerStyle}></div>\n          <div style={infoContainerStyle}>\n            <div style={roleStyle}>{titleText}</div>\n            <div style={subStyle}>{introText}</div>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n};"
