    thumb: "/thumbnails/8aedc1d6-c5c8-44f0-9f3d-9ed78fd55f69.png",
    code: "const FlowingDotGridCard = ({item}) => {\n  const frame = useCurrentFrame();\n\n  const props = item.props || {};\n  const bgColor = props.bgColor;\n  const dotColor = props.dotColor;\n  const screenshotImage = props.screenshotImage;\n  const cardShadowOpacity = props.cardShadowOpacity;\n  const transparentBackground = props.transparentBackground;\n\n  const DESIGN_WIDTH = 1920;\n  const DESIGN_HEIGHT = 1080;\n  const scale = Math.min(\n    (item?.width || DESIGN_WIDTH) / DESIGN_WIDTH,\n    (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT\n  );\n\n  const rootStyle = {\n    position: 'absolute',\n    top: 0, left: 0,\n    width: DESIGN_WIDTH, height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`,\n    transformOrigin: 'top left',\n    backgroundColor: transparentBackground ? 'transparent' : bgColor,\n    overflow: 'hidden',\n  };\n\n  const cols = 54;\n  const rows = 31;\n  const spacing = 38;\n  const fTime1 = frame * 0.03;\n  const fTime2 = frame * 0.02;\n\n  const dots = [];\n  for (let r = 0; r < rows; r++) {\n    for (let c = 0; c < cols; c++) {\n      const wave1 = Math.sin(c * 0.05 + r * 0.2 + fTime1);\n      const wave2 = Math.sin(c * 0.1 - r * 0.05 + fTime2);\n      const combinedWave = wave1 * 0.7 + wave2 * 0.3;\n      const opacity = 0.215 + combinedWave * 0.135;\n      const radius = 1.5 + combinedWave * 0.5;\n      dots.push(\n        <circle key={`${r}-${c}`} cx={c * spacing} cy={r * spacing} r={radius} fill={dotColor} opacity={opacity} />\n      );\n    }\n  }\n\n  const cardOpacity = interpolate(frame, [5, 25], [0, 1], { extrapolateRight: 'clamp' });\n  const cardScale = interpolate(frame, [5, 25], [0.92, 1], {\n    easing: Easing.out(Easing.cubic), extrapolateRight: 'clamp'\n  });\n\n  return (\n    <div style={rootStyle}>\n      <svg style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%' }}>\n        <g transform={`translate(${(DESIGN_WIDTH - (cols - 1) * spacing) / 2}, ${(DESIGN_HEIGHT - (rows - 1) * spacing) / 2})`}>\n          {dots}\n        </g>\n      </svg>\n\n      {screenshotImage ? (\n        <div style={{\n          position: 'absolute',\n          top: '50%', left: '50%',\n          transform: `translate(-50%, -50%) scale(${cardScale})`,\n          width: 1160, height: 652,\n          backgroundColor: '#ffffff',\n          borderRadius: 16,\n          boxShadow: `0 12px 48px rgba(0,0,0,${cardShadowOpacity})`,\n          opacity: cardOpacity,\n          overflow: 'hidden',\n          display: 'flex',\n          alignItems: 'center',\n          justifyContent: 'center',\n        }}>\n          <Img src={screenshotImage} style={{ width: '100%', height: '100%', objectFit: 'contain' }} />\n        </div>\n      ) : null}\n    </div>\n  );\n};\n"
