    thumb: "/thumbnails/4de08f53-df3a-47ed-bd45-e541386b27fa.jpg",
    code: "const PollCard = ({item}) => {\n  const baseFrame = useCurrentFrame();\n  const {fps, durationInFrames} = useVideoConfig();\n\n  const props = item.props || {};\n  const backgroundImage = props.backgroundImage;\n  const questionText = props.questionText;\n  const votesText = props.votesText;\n  const sourceName = props.sourceName;\n  const sourceTime = props.sourceTime;\n  const badgeColor = props.badgeColor;\n  const barColorWinner = props.barColorWinner;\n  const barColorOthers = props.barColorOthers;\n  const opt1Label = props.opt1Label;\n  const opt2Label = props.opt2Label;\n  const opt3Label = props.opt3Label;\n  const opt4Label = props.opt4Label;\n  const opt1Value = props.opt1Value;\n  const opt2Value = props.opt2Value;\n  const opt3Value = props.opt3Value;\n  const opt4Value = props.opt4Value;\n\n  const DESIGN_WIDTH = 1920;\n  const DESIGN_HEIGHT = 1080;\n\n  const frame = Math.floor(baseFrame / 3) * 3;\n  const rawProgress = interpolate(frame, [6, 54], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });\n  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);\n  const progress = easeOutCubic(rawProgress);\n\n  const options = [\n    { label: opt1Label, value: opt1Value, isWinner: true },\n    { label: opt2Label, value: opt2Value, isWinner: false },\n    { label: opt3Label, value: opt3Value, isWinner: false },\n    { label: opt4Label, value: opt4Value, isWinner: false },\n  ];\n\n  const total = options.reduce((s, o) => s + (o.value || 0), 0) || 100;\n\n  return (\n    <div style={{ position: 'absolute', top: 0, left: 0, width: DESIGN_WIDTH, height: DESIGN_HEIGHT, fontFamily: 'Roboto, sans-serif' }}>\n      {backgroundImage ? (\n        <Img src={backgroundImage} style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', objectFit: 'cover', zIndex: 0 }} />\n      ) : (\n        <div style={{ position: 'absolute', inset: 0, backgroundColor: '#a3b86e', zIndex: 0 }} />\n      )}\n\n      <div style={{ position: 'absolute', left: '17%', top: '19%', width: '66%', zIndex: 2, display: 'flex', flexDirection: 'column' }}>\n\n        <div style={{ display: 'flex', alignItems: 'center', gap: 20, marginBottom: 28 }}>\n          <div style={{ width: 72, height: 72, borderRadius: '50%', backgroundColor: badgeColor, display: 'flex', justifyContent: 'center', alignItems: 'center', fontWeight: 900, fontSize: 20, fontFamily: 'Roboto, sans-serif', color: '#fff', flexShrink: 0 }}>\n            {(sourceName || '').substring(0, 3).toUpperCase()}\n          </div>\n          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>\n            <span style={{ fontWeight: 800, fontSize: 30, color: '#000' }}>{sourceName}</span>\n            <span style={{ fontSize: 26, color: '#888' }}>{sourceTime}</span>\n          </div>\n        </div>\n\n        <div style={{ fontWeight: 700, fontSize: 36, color: '#000', marginBottom: 10, lineHeight: 1.35 }}>{questionText}</div>\n        <div style={{ fontSize: 24, color: '#888', marginBottom: 36 }}>{votesText}</div>\n\n        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>\n          {options.map((opt, i) => {\n            const pct = total > 0 ? Math.round((opt.value / total) * 100) : 0;\n            const barW = progress * pct;\n            const rollingNum = Math.floor(progress * pct);\n            const displayNum = frame >= 54 ? pct + '%' : rollingNum + '%';\n            return (\n              <div key={i} style={{ position: 'relative', width: '100%', height: 82, border: '1.5px solid rgba(0,0,0,0.12)', borderRadius: 8, overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 24px', boxSizing: 'border-box' }}>\n                <div style={{ position: 'absolute', top: 0, left: 0, bottom: 0, width: `${barW}%`, backgroundColor: opt.isWinner ? barColorWinner : barColorOthers, zIndex: 1 }} />\n                <div style={{ position: 'relative', zIndex: 2, fontSize: 26, fontWeight: 600, color: opt.isWinner ? '#000' : '#555' }}>{opt.label}</div>\n                <div style={{ position: 'relative', zIndex: 2, fontSize: opt.isWinner ? 44 : 30, fontWeight: opt.isWinner ? 800 : 600, color: opt.isWinner ? '#000' : '#444', minWidth: 120, textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{displayNum}</div>\n              </div>\n            );\n          })}\n        </div>\n      </div>\n    </div>\n  );\n};"
