            top: card.cy - CARD_H / 2,
            width: CARD_W,
            height: CARD_H,
            backgroundColor: '#dbe3f2',
            borderRadius: 18,
            display: 'flex',
            alignItems: 'center',
            paddingLeft: 16,
            boxSizing: 'border-box',
            opacity: anim.opacity,
