    code: "const BoldGlitchTitle05 = ({item}) => {\n  const frame = useCurrentFrame();\n  const {durationInFrames} = useVideoConfig();\n  const props = item.props || {};\n  const mainTitle = props.mainTitle || 'SHOP THE LOOK';\n  const subtitleText = props.subtitleText || 'COZY HOME COLLECTION';\n  const textColor = props.textColor || '#FFFFFF';\n  const glowColor = props.glowColor || 'rgba(255,255,255,0.5)';\n  const bgOpacity = props.bgOpacity !== undefined ? parseFloat(props.bgOpacity) : 0.88;\n\n  const DESIGN_WIDTH = 1920, DESIGN_HEIGHT = 1080;\n  const scale = Math.min((item?.width||DESIGN_WIDTH)/DESIGN_WIDTH, (item?.height||DESIGN_HEIGHT)/DESIGN_HEIGHT);\n\n  const outStart = Math.max(0, durationInFrames - 30);\n\n  let textOpacity = 1, shadowStr = 'none', scanI = 0.06;\n\n  if (frame < 8) {\n    textOpacity = 0.08; scanI = 0.35;\n  } else if (frame < 12) {\n    textOpacity = frame%2===0 ? 1 : 0.1;\n    scanI = 0.5;\n  } else if (frame < 25) {\n    const n = Math.abs(Math.sin(frame*12.9898)*43758.5453)%1;\n    textOpacity = n>0.3 ? 1 : 0.6;\n    const spread = n>0.5 ? 22 : 0;\n    shadowStr = `0 0 6px ${textColor}, 0 0 ${spread}px ${glowColor}`;\n    scanI = 0.3;\n  } else if (frame < outStart) {\n    const micro = (frame-25)%22<2;\n    textOpacity = micro ? 0.7 : 1;\n    shadowStr = `0 0 28px ${glowColor}`;\n    scanI = 0.06;\n  } else if (frame < outStart+10) {\n    const n = Math.abs(Math.sin(frame*78.233)*43758.5453)%1;\n    textOpacity = n>0.5 ? 1 : 0.15;\n    shadowStr = n>0.5 ? `0 0 22px ${glowColor}` : 'none';\n    scanI = 0.45;\n  } else {\n    const fp = (frame-(outStart+10))/20;\n    textOpacity = interpolate(fp,[0,1],[1,0],{extrapolateRight:'clamp'});\n    shadowStr = `0 0 ${interpolate(fp,[0,1],[30,0],{extrapolateRight:'clamp'})}px ${glowColor}`;\n    scanI = 0.3;\n  }\n\n  // Fine glitch slices during flicker phases\n  const isFlicker = frame < 25 || frame >= outStart;\n  const NUM_SLICES = 12;\n  const sliceShifts = Array.from({length:NUM_SLICES}).map((_,i) => {\n    if (!isFlicker) return 0;\n    const maxS = frame<12 ? 40 : 18;\n    const active = random(`fa${i}${Math.floor(frame/2)}`) > 0.72;\n    return active ? (random(`fs${i}${frame}`)-0.5)*2*maxS : 0;\n  });\n\n  // RGB offset during flicker\n  const rgbActive = frame < 25 || frame >= outStart;\n  const rOff = rgbActive ? (random('r'+frame)-0.5)*2*(frame<12?18:9) : 0;\n  const cOff = rgbActive ? (random('c'+frame)-0.5)*2*(frame<12?18:9)*-1 : 0;\n\n  const rootStyle = {\n    position:'absolute', top:0, left:0, width:DESIGN_WIDTH, height:DESIGN_HEIGHT,\n    transform:`scale(${scale})`, transformOrigin:'top left',\n    backgroundColor:`rgba(10,10,10,${bgOpacity})`, overflow:'hidden'\n  };\n\n  return (\n    <div style={rootStyle}>\n      {/* Scanlines */}\n      <div style={{\n        position:'absolute', top:0, left:0, width:'100%', height:'100%',\n        background:'repeating-linear-gradient(to bottom, transparent 0px, transparent 3px, rgba(0,0,0,0.4) 4px, rgba(0,0,0,0.4) 5px)',\n        opacity:scanI, pointerEvents:'none', mixBlendMode:'overlay', zIndex:20\n      }}/>\n\n      {/* RGB Red layer */}\n      {rOff !== 0 && <div style={{position:'absolute', top:0, left:rOff, width:'100%', height:'100%', mixBlendMode:'screen', opacity:0.55}}>\n        <div style={{position:'absolute', top:'48%', left:'50%', transform:'translate(-50%,-50%)',\n          fontFamily:'\"Montserrat\",\"Inter\",sans-serif', fontWeight:900, fontSize:'125px',\n          textTransform:'uppercase', color:'#789e00', whiteSpace:'nowrap', opacity:textOpacity}}>{mainTitle}</div>\n      </div>}\n      {/* RGB Cyan layer */}\n      {cOff !== 0 && <div style={{position:'absolute', top:0, left:cOff, width:'100%', height:'100%', mixBlendMode:'screen', opacity:0.55}}>\n        <div style={{position:'absolute', top:'48%', left:'50%', transform:'translate(-50%,-50%)',\n          fontFamily:'\"Montserrat\",\"Inter\",sans-serif', fontWeight:900, fontSize:'125px',\n          textTransform:'uppercase', color:'#00e8e9', whiteSpace:'nowrap', opacity:textOpacity}}>{mainTitle}</div>\n      </div>}\n\n      {/* Main text */}\n      <div style={{position:'absolute', top:'48%', left:'50%', transform:'translate(-50%,-50%)',\n        fontFamily:'\"Montserrat\",\"Inter\",sans-serif', fontWeight:900, fontSize:'125px',\n        textTransform:'uppercase', color:textColor, opacity:textOpacity, textShadow:shadowStr,\n        whiteSpace:'nowrap', textAlign:'center', lineHeight:1}}>{mainTitle}</div>\n\n      {/* Subtitle */}\n      <div style={{position:'absolute', top:'56%', left:'50%', transform:'translate(-50%,-50%)',\n        fontFamily:'\"Montserrat\",\"Inter\",sans-serif', fontWeight:400, fontSize:'20px',\n        letterSpacing:'0.2em', textTransform:'uppercase', color:textColor,\n        opacity:textOpacity, textShadow:shadowStr, whiteSpace:'nowrap', textAlign:'center', lineHeight:1}}>{subtitleText}</div>\n\n      {/* Fine glitch slice overlays */}\n      {sliceShifts.map((shift,i) => shift !== 0 && (\n        <div key={i} style={{\n          position:'absolute', top:0, left:shift, width:'100%', height:'100%',\n          clipPath:`inset(${(i/NUM_SLICES)*100}% 0 ${100-((i+1)/NUM_SLICES)*100}% 0)`\n        }}>\n          <div style={{position:'absolute', top:'48%', left:'50%', transform:'translate(-50%,-50%)',\n            fontFamily:'\"Montserrat\",\"Inter\",sans-serif', fontWeight:900, fontSize:'125px',\n            textTransform:'uppercase', color:textColor, opacity:textOpacity*0.8,\n            textShadow:shadowStr, whiteSpace:'nowrap'}}>{mainTitle}</div>\n        </div>\n      ))}\n    </div>\n  );\n};\n"
