  const headerLabel3 = props.headerLabel3 || 'YOU\u2019RE IN';
  // Background watermark text strips
  const bgText1 = props.bgText1 || 'You\u2019re In';
  const bgText2 = props.bgText2 || 'Glad you found us';
  const bgText3 = props.bgText3 || 'THE CREW';
