    code: "const Component = ({item}) => {\n  const frame = useCurrentFrame();\n  const {fps} = useVideoConfig();\n  const safeFps = fps || 30;\n\n  const props = item.props || {};\n  const startNumber = parseInt(props.startNumber || '10', 10);\n  const endNumber = parseInt(props.endNumber || '1', 10);\n  const tickerText = props.tickerText || 'LAUNCHING IN';\n  const subText = props.subText || 'UNTIL LIVE';\n  \n  const accentColor = props.accentColor || '#86b000';\n  const bgColor = props.bgColor || '#FFFFFF';\n  const textColor = props.textColor || '#000000';\n  const headerTextColor = props.headerTextColor || '#FFFFFF';\n  \n  const numberFont = props.numberFont || '\"VT323\", monospace';\n  const textFont = props.textFont || '\"Silkscreen\", cursive';\n\n  const DESIGN_WIDTH = 480;\n  const DESIGN_HEIGHT = 220;\n  const scale = Math.min(\n    (item?.width || DESIGN_WIDTH) / DESIGN_WIDTH,\n    (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT\n  );\n\n  const safeSpring = (delay = 0, config = { damping: 15 }) => {\n    return spring({ frame: Math.max(0, frame - delay), fps: safeFps, config });\n  };\n\n  // Animations\n  const bounceScale = safeSpring(0, { damping: 12, stiffness: 120 });\n  \n  // Countdown logic: starts 1 second (safeFps frames) after bounce begins\n  const countdownStartFrame = safeFps;\n  const elapsedFrames = Math.max(0, frame - countdownStartFrame);\n  const secondsPassed = Math.floor(elapsedFrames / safeFps);\n  const currentNumber = startNumber - secondsPassed;\n  const displayNum = Math.max(endNumber, Math.min(startNumber, currentNumber));\n\n  // Ticker logic\n  const tickerX = -(frame * 1.5);\n  const repeatedTickerText = React.useMemo(() => {\n    return new Array(100).fill(tickerText).join(' \u2022 ');\n  }, [tickerText]);\n\n  const rootStyle = {\n    position: 'absolute',\n    top: 0,\n    left: 0,\n    width: DESIGN_WIDTH,\n    height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`,\n    transformOrigin: 'top left',\n    backgroundColor: 'transparent',\n    display: 'flex',\n    justifyContent: 'center',\n    alignItems: 'center'\n  };\n\n  const cardStyle = {\n    width: 260,\n    height: 150,\n    backgroundColor: bgColor,\n    border: '2px solid #000',\n    boxShadow: '4px 4px 0px #000, 8px 8px 0px rgba(0,0,0,0.2)',\n    display: 'flex',\n    flexDirection: 'column',\n    transform: `scale(${bounceScale})`,\n    boxSizing: 'border-box'\n  };\n\n  const headerStyle = {\n    height: 24,\n    backgroundColor: accentColor,\n    borderBottom: '2px solid #000',\n    display: 'flex',\n    alignItems: 'center',\n    overflow: 'hidden',\n    whiteSpace: 'nowrap',\n    boxSizing: 'border-box',\n    position: 'relative'\n  };\n\n  const tickerStyle = {\n    fontFamily: textFont,\n    fontSize: 10,\n    color: headerTextColor,\n    transform: `translateX(${tickerX}px)`,\n    letterSpacing: 1,\n    paddingLeft: 10\n  };\n\n  const bodyStyle = {\n    flex: 1,\n    display: 'flex',\n    flexDirection: 'column',\n    justifyContent: 'center',\n    alignItems: 'center',\n    position: 'relative',\n    overflow: 'hidden'\n  };\n\n  const numberStyle = {\n    fontFamily: numberFont,\n    fontSize: 80,\n    lineHeight: 1,\n    color: textColor,\n    margin: 0,\n    marginTop: 10,\n    textShadow: '2px 2px 0px rgba(0,0,0,0.1)'\n  };\n\n  const subTextStyle = {\n    fontFamily: textFont,\n    fontSize: 11,\n    color: textColor,\n    marginTop: 4,\n    letterSpacing: 1,\n    textTransform: 'uppercase'\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={cardStyle}>\n        <div style={headerStyle}>\n          <div style={tickerStyle}>\n            {repeatedTickerText}\n          </div>\n        </div>\n        <div style={bodyStyle}>\n          <div style={numberStyle}>{displayNum}</div>\n          <div style={subTextStyle}>{subText}</div>\n        </div>\n      </div>\n    </div>\n  );\n};"
