    code: "const Component = ({item}) => {\n  const frame = useCurrentFrame();\n  const {fps} = useVideoConfig();\n\n  const props = item.props || {};\n  const leftName = props.leftNameText || 'MAYA REYES';\n  const leftRole = props.leftSubtitleText || 'INTERIOR STYLIST';\n  const leftColor = props.leftAvatarColor || '#baf125';\n  const rightName = props.rightNameText || 'OWEN PARK';\n  const rightRole = props.rightSubtitleText || 'SHOP CURATOR';\n  const rightColor = props.rightAvatarColor || '#00bfbf';\n  const cardBgColor = props.cardBgColor || '#FFFFFF';\n  const borderColor = props.borderColor || '#000000';\n  const fontFamily = props.fontFamily || '\"Press Start 2P\", monospace';\n\n  const DESIGN_WIDTH = 640;\n  const DESIGN_HEIGHT = 240;\n  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);\n\n  const scaleAnim = spring({\n    frame,\n    fps,\n    config: { damping: 12, stiffness: 150 }\n  });\n\n  const opacityAnim = spring({\n    frame,\n    fps,\n    config: { damping: 20, stiffness: 200 }\n  });\n\n  const rootStyle = {\n    position: 'absolute',\n    top: 0,\n    left: 0,\n    width: DESIGN_WIDTH,\n    height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`,\n    transformOrigin: 'top left',\n    display: 'flex',\n    justifyContent: 'center',\n    alignItems: 'center',\n    fontFamily: fontFamily,\n    color: borderColor,\n    textTransform: 'uppercase',\n    backgroundColor: 'transparent',\n  };\n\n  const cardStyle = {\n    width: 540,\n    height: 180,\n    backgroundColor: cardBgColor,\n    border: `2px solid ${borderColor}`,\n    boxShadow: `8px 8px 0px 0px ${borderColor}`,\n    display: 'flex',\n    flexDirection: 'row',\n    transform: `scale(${scaleAnim})`,\n    opacity: Math.min(1, opacityAnim * 2),\n    boxSizing: 'border-box',\n  };\n\n  const columnStyle = {\n    flex: 1,\n    display: 'flex',\n    flexDirection: 'column',\n    alignItems: 'center',\n    justifyContent: 'center',\n    gap: '14px',\n    height: '100%',\n  };\n\n  const dividerStyle = {\n    width: '2px',\n    backgroundColor: borderColor,\n    height: '100%',\n  };\n\n  const avatarStyle = (bgColor) => ({\n    width: 64,\n    height: 64,\n    borderRadius: '50%',\n    backgroundColor: bgColor,\n    border: `2px solid ${borderColor}`,\n    boxShadow: `4px 4px 0px 0px ${borderColor}`,\n    flexShrink: 0,\n  });\n\n  const textContainerStyle = {\n    display: 'flex',\n    flexDirection: 'column',\n    alignItems: 'center',\n    gap: '8px',\n  };\n\n  const nameStyle = {\n    fontSize: '14px',\n    fontWeight: 'bold',\n    letterSpacing: '1px',\n    textAlign: 'center',\n  };\n\n  const roleStyle = {\n    fontSize: '10px',\n    opacity: 0.8,\n    letterSpacing: '0.5px',\n    textAlign: 'center',\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={cardStyle}>\n        <div style={columnStyle}>\n           <div style={avatarStyle(leftColor)}></div>\n           <div style={textContainerStyle}>\n             <div style={nameStyle}>{leftName}</div>\n             <div style={roleStyle}>{leftRole}</div>\n           </div>\n        </div>\n        <div style={dividerStyle}></div>\n        <div style={columnStyle}>\n           <div style={avatarStyle(rightColor)}></div>\n           <div style={textContainerStyle}>\n             <div style={nameStyle}>{rightName}</div>\n             <div style={roleStyle}>{rightRole}</div>\n           </div>\n        </div>\n      </div>\n    </div>\n  );\n};"
