    code: "const RetroPixelCard = ({ item }) => {\n  const frame = useCurrentFrame();\n  const { fps } = useVideoConfig();\n  const props = item.props || {};\n\n  // Properties with defaults\n  const titleText = props.titleText || 'MARCUS OKAFOR';\n  const subtitleText = props.subtitleText || 'LEAD GAME DESIGNER';\n  const headerColor = props.headerColor || '#ffaaf3';\n  const headerTextColor = props.headerTextColor || '#000000';\n  const subtitleBgColor = props.subtitleBgColor || '#1A1A1A';\n  const subtitleTextColor = props.subtitleTextColor || '#FFFFFF';\n  const borderColor = props.borderColor || '#000000';\n  const fontFamily = props.fontFamily || '\\'VT323\\', monospace';\n\n  // Canvas dimensions\n  const DESIGN_WIDTH = 600;\n  const DESIGN_HEIGHT = 220;\n  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);\n\n  // Animation: Elastic pop-in\n  const entrance = spring({\n    frame,\n    fps,\n    config: {\n      damping: 12,\n      stiffness: 120,\n      mass: 0.6\n    }\n  });\n\n  // Root container for responsive scaling\n  const rootStyle = {\n    position: 'absolute',\n    top: 0,\n    left: 0,\n    width: DESIGN_WIDTH,\n    height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`,\n    transformOrigin: 'top left',\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    fontFamily: fontFamily,\n  };\n\n  // Card container (the visible element)\n  const cardStyle = {\n    position: 'relative',\n    display: 'flex',\n    flexDirection: 'column',\n    border: `3px solid ${borderColor}`,\n    boxShadow: `8px 8px 0px 0px ${borderColor}`,\n    transform: `scale(${entrance})`,\n    backgroundColor: '#ffffff',\n    maxWidth: '90%',\n    minWidth: '320px',\n  };\n\n  const headerStyle = {\n    backgroundColor: headerColor,\n    color: headerTextColor,\n    padding: '12px 24px',\n    fontSize: '48px',\n    lineHeight: 1,\n    fontWeight: 'bold',\n    borderBottom: `3px solid ${borderColor}`,\n    textTransform: 'uppercase',\n    textAlign: 'center',\n    whiteSpace: 'nowrap',\n    overflow: 'hidden',\n    textOverflow: 'ellipsis',\n  };\n\n  const subtitleStyle = {\n    backgroundColor: subtitleBgColor,\n    color: subtitleTextColor,\n    padding: '8px 24px',\n    fontSize: '24px',\n    lineHeight: 1.2,\n    textAlign: 'center',\n    textTransform: 'uppercase',\n    letterSpacing: '1px',\n    whiteSpace: 'nowrap',\n    overflow: 'hidden',\n    textOverflow: 'ellipsis',\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={cardStyle}>\n        <div style={headerStyle}>\n          {titleText}\n        </div>\n        <div style={subtitleStyle}>\n          {subtitleText}\n        </div>\n      </div>\n    </div>\n  );\n};"
