    code: `const HoloBg = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const props = item.props || {};

  const accentColor = props.accentColor || '#9e7fff';
  const fontFamily = props.fontFamily || 'Inter, sans-serif';

  const DESIGN_WIDTH = 1920;
  const DESIGN_HEIGHT = 1080;

  const scale = Math.min(
    (item?.width || DESIGN_WIDTH) / DESIGN_WIDTH,
    (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT
  );

  const sparkleProgress = interpolate(frame, [0, durationInFrames], [0, 1], { extrapolateRight: 'clamp' });

  const rootStyle = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: DESIGN_WIDTH,
    height: DESIGN_HEIGHT,
    backgroundColor: '#F9F9F9',
    overflow: 'hidden',
    transform: \`scale(\${scale})\`,
    transformOrigin: 'top left',
    fontFamily
  };

  const chromeShadow = '4px 4px 0px rgba(0,0,0,0.1)';

  return (
    <div style={rootStyle}>
      {/* Background Blobs */}
      <div style={{ position: 'absolute', top: '-10%', left: '-5%', width: 800, height: 800, borderRadius: '50%', background: '#ff9f90', filter: 'blur(150px)', opacity: 0.5 }} />
      <div style={{ position: 'absolute', top: '-10%', right: '-5%', width: 900, height: 900, borderRadius: '50%', background: accentColor, filter: 'blur(150px)', opacity: 0.4 }} />
      <div style={{ position: 'absolute', bottom: '-10%', right: '10%', width: 800, height: 800, borderRadius: '50%', background: '#a68300', filter: 'blur(150px)', opacity: 0.5 }} />

      {/* Top Tabs */}
      <div style={{ position: 'absolute', top: 60, left: 100, display: 'flex', gap: 15 }}>
        {[0, 1, 2].map((i) => (
          <div key={i} style={{ width: 100, height: 36, border: '3px solid black', borderRadius: 18, backgroundColor: i === 0 ? '#fff' : 'transparent', boxShadow: chromeShadow }} />
        ))}
      </div>
      {/* Hamburger */}
      <div style={{ position: 'absolute', top: 65, right: 100, display: 'flex', flexDirection: 'column', gap: 6 }}>
        {[0, 1, 2].map(i => <div key={i} style={{ width: 40, height: 4, background: 'black', borderRadius: 2 }} />)}
      </div>

      {/* Left Triangles */}
      <div style={{ position: 'absolute', left: 80, top: '42%' }}>
        <svg width="60" height="120" viewBox="0 0 60 120" fill="none" stroke="black" strokeWidth="4">
          <path d="M 10 10 L 50 35 L 10 60 Z" stroke="#009b9b" fill="rgba(0,155,155, 0.1)" />
          <path d="M 10 70 L 50 95 L 10 120 Z" stroke="#fc5ed1" fill="rgba(252,94,209, 0.1)" />
        </svg>
      </div>

      {/* Right Dots */}
      <div style={{ position: 'absolute', right: 80, top: '42%', display: 'flex', flexDirection: 'column', gap: 18 }}>
        {[0, 1, 2, 3].map(i => (
          <div key={i} style={{ width: 18, height: 18, border: '3px solid black', borderRadius: '50%', backgroundColor: i === 3 ? '#fc5ed1' : 'transparent' }} />
        ))}
      </div>

      {/* Bottom Timeline & Sparkle */}
      <div style={{ position: 'absolute', bottom: 100, left: 150, right: 150, height: 4, backgroundColor: 'black', borderRadius: 2 }}>
        <div style={{ position: 'absolute', left: -10, top: -8, width: 20, height: 20, background: 'black', transform: 'rotate(45deg)' }} />
        <div style={{ position: 'absolute', right: -10, top: -8, width: 20, height: 20, background: 'black', transform: 'rotate(45deg)' }} />
        <div style={{
          position: 'absolute',
          left: 0, top: -28,
          transform: \`translateX(\${interpolate(sparkleProgress, [0, 1], [0, 1620])}px) rotate(\${frame * 3}deg)\`
        }}>
          <svg width="60" height="60" viewBox="0 0 60 60">
            <path d="M30 0 C30 0 38 22 60 30 C38 38 30 60 30 60 C30 60 22 38 0 30 C22 22 30 0 30 0 Z" fill="#dad3ff" stroke="black" strokeWidth="2" />
          </svg>
        </div>
      </div>
    </div>
  );
};
`
