    code: "const ChapterTitle = ({item}) => {\n  const frame = useCurrentFrame();\n  const {fps, durationInFrames} = useVideoConfig();\n\n  const props = item.props || {};\n  const numberText = props.numberText;\n  const titleLine1 = props.titleLine1;\n  const titleLine2 = props.titleLine2;\n  const accentColor = props.accentColor;\n  const textColor = props.textColor;\n  const bgColor = props.bgColor;\n  const fontFamily = props.fontFamily;\n  const transparentBackground = props.transparentBackground;\n\n  const DESIGN_WIDTH = 1920;\n  const DESIGN_HEIGHT = 1080;\n  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);\n\n  const easeOutCubic = Easing.out(Easing.cubic);\n\n  // Icon animation: duration 18f, delay 3f\n  const iconScale = interpolate(frame, [3, 21], [0.6, 1], {\n    easing: easeOutCubic,\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp'\n  });\n  const iconOpacity = interpolate(frame, [3, 21], [0, 1], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp'\n  });\n\n  // Line 1 animation: duration 16f, delay 14f\n  const line1X = interpolate(frame, [14, 30], [-30, 0], {\n    easing: easeOutCubic,\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp'\n  });\n  const line1Opacity = interpolate(frame, [14, 30], [0, 1], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp'\n  });\n\n  // Line 2 animation: duration 16f, delay 22f\n  const line2X = interpolate(frame, [22, 38], [-30, 0], {\n    easing: easeOutCubic,\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp'\n  });\n  const line2Opacity = interpolate(frame, [22, 38], [0, 1], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp'\n  });\n\n  const rootStyle = {\n    position: 'absolute',\n    top: 0,\n    left: 0,\n    width: DESIGN_WIDTH,\n    height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`,\n    transformOrigin: 'top left',\n    backgroundColor: transparentBackground ? 'transparent' : bgColor,\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    fontFamily: fontFamily,\n    overflow: 'hidden',\n  };\n\n  const contentStyle = {\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n  };\n\n  const iconBoxStyle = {\n    width: 140,\n    height: 140,\n    backgroundColor: '#FFFFFF',\n    borderRadius: 24,\n    boxShadow: '0 4px 20px rgba(0,0,0,0.10)',\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    transform: `scale(${iconScale})`,\n    opacity: iconOpacity,\n    flexShrink: 0,\n  };\n\n  const numberStyle = {\n    color: accentColor,\n    fontSize: 80,\n    fontWeight: 900,\n    margin: 0,\n    lineHeight: 1,\n  };\n\n  const textContainerStyle = {\n    display: 'flex',\n    flexDirection: 'column',\n    marginLeft: 40,\n  };\n\n  const textLineBaseStyle = {\n    color: textColor,\n    fontSize: 72,\n    fontWeight: 900,\n    lineHeight: 1.2,\n    margin: 0,\n    whiteSpace: 'nowrap',\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={contentStyle}>\n        <div style={iconBoxStyle}>\n          <span style={numberStyle}>{numberText}</span>\n        </div>\n        <div style={textContainerStyle}>\n          <div style={{ opacity: line1Opacity, transform: `translateX(${line1X}px)` }}>\n            <h1 style={textLineBaseStyle}>{titleLine1}</h1>\n          </div>\n          <div style={{ opacity: line2Opacity, transform: `translateX(${line2X}px)` }}>\n            <h1 style={textLineBaseStyle}>{titleLine2}</h1>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n};"
