    code: "const SplitIntroCard = ({item}) => {\n  const frame = useCurrentFrame();\n  const {durationInFrames} = useVideoConfig();\n\n  const props = item.props || {};\n  const bgColor = props.transparentBackground ? 'transparent' : props.bgColor;\n  const leftPanelColor = props.leftPanelColor;\n  const photoUrl = props.photoUrl;\n\n  const titleText = props.titleText;\n  const bodyText = props.bodyText;\n  const titleFont = props.titleFont;\n  const bodyFont = props.bodyFont;\n  const titleColor = props.titleColor;\n  const bodyColor = props.bodyColor;\n\n  // --- Easing ---\n  const smoothSettle = (t) => {\n    if (t <= 0) return 0;\n    if (t >= 1) return 1;\n    return 1 - Math.pow(1 - t, 3.5);\n  };\n\n  // --- Exit ---\n  const totalFrames = durationInFrames || 150;\n  const exitStart = totalFrames - 25;\n  const exitRaw = Math.max(0, Math.min(1, (frame - exitStart) / 25));\n  const exitProgress = exitRaw * exitRaw;\n  const exitOpacity = 1 - exitProgress;\n  const exitScale = 1 - exitProgress * 0.02;\n\n  // --- Left panel slide in: frame 0, 50 frames ---\n  const leftRaw = Math.min(1, Math.max(0, frame / 50));\n  const leftProgress = smoothSettle(leftRaw);\n  const leftPanelTranslate = (1 - leftProgress) * -100;\n\n  // --- Photo subtle scale (continuous, from 1.05 to 1.0) ---\n  const photoScale = 1.05 - 0.05 * smoothSettle(Math.min(1, Math.max(0, frame / 90)));\n\n  // --- Title: starts at frame 25, 50 frames ---\n  const titleRaw = Math.min(1, Math.max(0, (frame - 25) / 50));\n  const titleProgress = smoothSettle(titleRaw);\n  const titleOpacity = smoothSettle(Math.min(1, Math.max(0, (frame - 25) / 18)));\n  const titleY = (1 - titleProgress) * 60;\n\n  // --- Body text: starts at frame 55, 40 frames ---\n  const bodyRaw = Math.min(1, Math.max(0, (frame - 55) / 40));\n  const bodyProgress = smoothSettle(bodyRaw);\n  const bodyOpacity = smoothSettle(Math.min(1, Math.max(0, (frame - 55) / 15)));\n  const bodyY = (1 - bodyProgress) * 40;\n\n  const rootStyle = {\n    position: 'absolute',\n    inset: 0,\n    backgroundColor: bgColor,\n    overflow: 'hidden',\n    opacity: exitOpacity,\n    transform: `scale(${exitScale})`\n  };\n\n  const rightPanelStyle = {\n    position: 'absolute',\n    right: 0,\n    width: '65%',\n    height: '100%',\n    display: 'flex',\n    flexDirection: 'column',\n    justifyContent: 'center',\n    padding: '0 120px',\n    boxSizing: 'border-box'\n  };\n\n  const leftPanelStyle = {\n    position: 'absolute',\n    left: 0,\n    width: '35%',\n    height: '100%',\n    transform: `translateX(${leftPanelTranslate}%)`,\n    overflow: 'hidden'\n  };\n\n  const titleStyle = {\n    fontFamily: titleFont,\n    fontSize: '96px',\n    color: titleColor,\n    margin: '0 0 40px 0',\n    opacity: titleOpacity,\n    transform: `translateY(${titleY}px)`,\n    lineHeight: 1.1\n  };\n\n  const bodyStyle = {\n    fontFamily: bodyFont,\n    fontSize: '30px',\n    color: bodyColor,\n    margin: 0,\n    lineHeight: 1.5,\n    opacity: bodyOpacity,\n    transform: `translateY(${bodyY}px)`,\n    maxWidth: '800px',\n    whiteSpace: 'pre-wrap'\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={rightPanelStyle}>\n        <h1 style={titleStyle}>{titleText}</h1>\n        <p style={bodyStyle}>{bodyText}</p>\n      </div>\n\n      <div style={leftPanelStyle}>\n        {photoUrl && (\n          <Img\n            src={photoUrl}\n            style={{ width: '100%', height: '100%', objectFit: 'cover', transform: `scale(${photoScale})` }}\n          />\n        )}\n        <div style={{ position: 'absolute', inset: 0, backgroundColor: leftPanelColor }}></div>\n      </div>\n    </div>\n  );\n};"
