            <circle cx="150" cy="450" r="450" fill="url(#gradPeach)" />
            
            {/* Stem and soft foliage */}
            <path d="M 300,1000 C 400,800 350,600 380,450" fill="none" stroke={hexToRgba(washPeach, 0.4)} strokeWidth="4" />
            
            {/* Leaves on stem sides */}
            <path d={getLeafStr(-50, 0.7, 330, 720)} fill="url(#gradPeachLeaf)" />
