    code: "const Component = ({ item }) => {\n  const frame = useCurrentFrame();\n  const { fps } = useVideoConfig();\n  const props = item.props || {};\n\n  const safeFps = fps || 30;\n  const safeSpring = (delay) => spring({ frame: Math.max(0, frame - delay), fps: safeFps, config: { damping: 15 } });\n\n  const backgroundColor = props.transparentBackground ? 'transparent' : props.bgColor;\n  \n  // Timings based on prompt\n  const titleP = safeSpring(0);\n  const bar1P = safeSpring(36);\n  const bar2P = safeSpring(46);\n  const bar3P = safeSpring(56);\n  const nameTagP = safeSpring(72);\n  const b1P = safeSpring(108);\n  const b2P = safeSpring(120);\n  const b3P = safeSpring(132);\n  const quoteP = safeSpring(150);\n  const tlLine = safeSpring(174);\n  const tlN1 = safeSpring(184);\n  const tlN2 = safeSpring(194);\n  const tlN3 = safeSpring(204);\n  const tlN4 = safeSpring(214);\n\n  const chartData = [\n    { text: props.chartL1, width: 78, p: bar1P },\n    { text: props.chartL2, width: 85, p: bar2P },\n    { text: props.chartL3, width: 92, p: bar3P },\n  ];\n\n  const bullets = [props.bullet1, props.bullet2, props.bullet3];\n  const bSprings = [b1P, b2P, b3P];\n\n  const nodes = [\n    { label: props.time1, p: tlN1 },\n    { label: props.time2, p: tlN2 },\n    { label: props.time3, p: tlN3 },\n    { label: props.time4, p: tlN4 },\n  ];\n\n  return (\n    <div style={{ position: 'absolute', inset: 0, backgroundColor, overflow: 'hidden' }}>\n      {/* Name Tag (Top-left area) */}\n      <div style={{ position: 'absolute', top: 120, left: 120, opacity: nameTagP, transform: `translateY(${(1 - nameTagP) * -20}px)` }}>\n        <div style={{ backgroundColor: props.textColor, color: backgroundColor, padding: '8px 20px', fontFamily: props.titleFontFamily, fontSize: 28, display: 'inline-block', textTransform: 'uppercase' }}>\n          {props.nameTagTop}\n        </div>\n        <div style={{ padding: '8px 20px', fontFamily: props.bodyFontFamily, fontSize: 24, border: `3px solid ${props.textColor}`, borderTop: 'none', display: 'inline-block', color: props.textColor }}>\n          {props.nameTagBottom}\n        </div>\n      </div>\n\n      {/* Bullet Points (Top-left) */}\n      <div style={{ position: 'absolute', top: 280, left: 120, width: 800 }}>\n        {bullets.map((b, i) => (\n          <div key={i} style={{ display: 'flex', alignItems: 'flex-start', marginBottom: 24, opacity: bSprings[i], transform: `translateX(${(1 - bSprings[i]) * -20}px)` }}>\n            <div style={{ width: 16, height: 16, backgroundColor: props.textColor, marginRight: 24, marginTop: 12, borderRadius: '50%' }} />\n            <div style={{ fontFamily: props.bodyFontFamily, fontSize: 28, color: props.textColor, lineHeight: 1.4 }}>{b}</div>\n          </div>\n        ))}\n      </div>\n\n      {/* Chapter Title (Bottom-left) */}\n      <div style={{ position: 'absolute', top: 600, left: 120, width: 900 }}>\n        <h1 style={{ fontFamily: props.titleFontFamily, fontSize: 52, color: props.textColor, margin: 0, lineHeight: 1.25, opacity: titleP, transform: `translateY(${(1 - titleP) * 30}px)` }}>\n          {props.titleText}\n        </h1>\n      </div>\n\n      {/* Data Chart (Top-right) */}\n      <div style={{ position: 'absolute', top: 180, left: 1100, width: 650 }}>\n        {chartData.map((item, i) => (\n          <div key={i} style={{ marginBottom: 48 }}>\n            <div style={{ fontFamily: props.titleFontFamily, fontSize: 28, marginBottom: 16, color: props.textColor, display: 'flex', justifyContent: 'space-between', opacity: item.p }}>\n              <span>{item.text.split(' ')[0]}</span>\n              <span style={{ color: props.accentColor }}>{item.text.split(' ')[1] || ''}</span>\n            </div>\n            <div style={{ width: '100%', height: 32, border: `2px solid ${props.textColor}`, padding: 4, opacity: item.p }}>\n               <div style={{ width: `${item.width * item.p}%`, height: '100%', backgroundColor: props.accentColor, transformOrigin: 'left' }} />\n            </div>\n          </div>\n        ))}\n      </div>\n\n      {/* Highlight Quote (Bottom area - right) */}\n      <div style={{ position: 'absolute', top: 680, left: 1100, width: 650 }}>\n        <div style={{ fontFamily: props.quoteFontFamily, fontSize: 36, color: props.textColor, opacity: quoteP, transform: `translateY(${(1 - quoteP) * 20}px)`, lineHeight: 1.4 }}>\n          \"{props.quoteText}\"\n        </div>\n      </div>\n\n      {/* Timeline (Bottom full-width) */}\n      <div style={{ position: 'absolute', top: 920, left: 120, width: 1680, height: 100 }}>\n        <div style={{ position: 'absolute', top: 10, left: 0, right: 0, height: 4, width: `${tlLine * 100}%`, backgroundColor: props.textColor, transformOrigin: 'left' }} />\n        {nodes.map((node, i) => {\n          const leftPercent = (i / (nodes.length - 1)) * 100;\n          return (\n            <div key={i} style={{ position: 'absolute', left: `${leftPercent}%`, top: 0, transform: 'translateX(-50%)', opacity: node.p, display: 'flex', flexDirection: 'column', alignItems: 'center' }}>\n              <div style={{ width: 24, height: 24, borderRadius: '50%', backgroundColor: props.accentColor, border: `4px solid ${props.textColor}` }} />\n              <div style={{ fontFamily: props.titleFontFamily, fontSize: 24, color: props.textColor, marginTop: 10 }}>{node.label}</div>\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n};"
