    thumb: "/thumbnails/82cf935e-d02a-496b-bad3-12a3876328a9.jpg",
    code: "const TitleReveal = ({item}) => {\n  const frame = useCurrentFrame();\n  const {durationInFrames} = useVideoConfig();\n\n  // ---- BAKED VALUES (from timeline item overrides + asset defaults) ----\n  const mainText = \"CHAPTER FOUR\";\n  const bgColor = \"#527692\";\n  const textColor = \"#ffffff\";\n  const dotColor = \"#350b21\";\n  const fontFamily = \"'Arial Black', 'Impact', sans-serif\";\n  // -----------------------------------------------------------------------\n\n  const DESIGN_WIDTH = 1920;\n  const DESIGN_HEIGHT = 1080;\n\n  const scale = Math.min(\n    (item?.width || DESIGN_WIDTH) / DESIGN_WIDTH,\n    (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT\n  );\n\n  const lines = String(mainText)\n    .split(/\\n|<br\\s*\\/?>/ )\n    .map((l) => l.trim())\n    .filter(Boolean);\n\n  const bgMoveX = frame * 0.28;\n  const bgMoveY = Math.sin(frame * 0.025) * 12;\n\n  const titleReveal = interpolate(frame, [0, 45], [0, 1], {\n    easing: Easing.bezier(0.16, 1, 0.3, 1),\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n  });\n  const titleX = interpolate(titleReveal, [0, 1], [-DESIGN_WIDTH * 0.7, 0], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n  });\n\n  const titleBlurRaw = interpolate(frame, [0, 45], [20, 0], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n  });\n  const titleBlur = Math.round(titleBlurRaw * 2) / 2;\n\n  const microX = interpolate(frame, [32, 70], [-60, 0], {\n    easing: Easing.bezier(0.16, 1, 0.3, 1),\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n  });\n\n  const microBlurRaw = interpolate(frame, [32, 55], [8, 0], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n  });\n  const microBlur = Math.round(microBlurRaw * 2) / 2;\n\n  const microAlpha = interpolate(frame, [32, 70], [0, 1], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n  });\n\n  const hexToRgb = (hex) => {\n    const h = (hex || '#ffffff').replace('#', '');\n    return {\n      r: parseInt(h.substring(0,2), 16),\n      g: parseInt(h.substring(2,4), 16),\n      b: parseInt(h.substring(4,6), 16),\n    };\n  };\n  const tc = hexToRgb(textColor);\n\n  const dots = React.useMemo(() => {\n    const arr = [];\n    let seed = 12;\n    const rand = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };\n    for (let c = -2; c <= 54; c++) {\n      for (let r = -2; r <= 32; r++) {\n        arr.push({\n          x: c * 38 + (rand() - 0.5) * 8,\n          y: r * 38 + (rand() - 0.5) * 8,\n          size: 1.1 + rand() * 1.6,\n          phase: rand() * Math.PI * 2,\n        });\n      }\n    }\n    return arr;\n  }, []);\n\n  const bgTexts = React.useMemo(() => {\n    const arr = [];\n    const rows = [\n      {y: 30, even: true}, {y: 175, even: false}, {y: 320, even: true},\n      {y: 740, even: true}, {y: 885, even: false}, {y: 1030, even: true},\n    ];\n    for (const {y, even} of rows) {\n      for (let c = -1; c <= 8; c++) {\n        arr.push({ x: c * 315 + (even ? 0 : 150), y });\n      }\n    }\n    return arr;\n  }, []);\n\n  const label = String(mainText).replace(/\\n/g, ' ').toUpperCase();\n  const titleTop = lines.length > 1 ? '42%' : '50%';\n  const titleTranslate = lines.length > 1 ? 'translate(-50%, -100%)' : 'translate(-50%, -50%)';\n\n  return (\n    <div style={{\n      position: 'absolute', top: 0, left: 0,\n      width: DESIGN_WIDTH, height: DESIGN_HEIGHT,\n      transform: scale === 1 ? 'scale(1)' : `scale(${scale})`,\n      transformOrigin: 'top left',\n      backgroundColor: bgColor,\n      overflow: 'hidden',\n    }}>\n      <div style={{\n        position: 'absolute', inset: 0,\n        background: 'radial-gradient(circle at 28% 44%, rgba(255,255,255,0.04), transparent 30%), radial-gradient(circle at 74% 38%, rgba(0,0,0,0.06), transparent 34%)',\n      }} />\n\n      <svg width={DESIGN_WIDTH} height={DESIGN_HEIGHT}\n        style={{ position: 'absolute', inset: 0, transform: `translate(${bgMoveX}px,${bgMoveY}px)` }}>\n        {dots.map((d, i) => {\n          const pulse = Math.sin(frame * 0.035 + d.phase);\n          return (\n            <circle key={i} cx={d.x} cy={d.y}\n              r={Math.max(0.4, d.size + pulse * 0.28)}\n              fill={dotColor}\n              opacity={0.34 + pulse * 0.12}\n            />\n          );\n        })}\n      </svg>\n\n      <div style={{\n        position: 'absolute', inset: 0,\n        transform: `translateX(${microX}px)`,\n      }}>\n        {bgTexts.map((t, i) => (\n          <div key={i} style={{\n            position: 'absolute',\n            left: t.x, top: t.y,\n            fontFamily, fontSize: 13, fontWeight: 900,\n            color: `rgba(${tc.r},${tc.g},${tc.b},${microAlpha * 0.58})`,\n            textTransform: 'uppercase',\n            whiteSpace: 'nowrap',\n            filter: microBlur > 0 ? `blur(${microBlur}px)` : 'none',\n          }}>\n            {label}\n          </div>\n        ))}\n      </div>\n\n      <div style={{ position: 'absolute', inset: 0, overflow: 'hidden' }}>\n        <div style={{\n          position: 'absolute', inset: 0,\n          transform: `translateX(${titleX}px)`,\n        }}>\n          {lines.map((line, i) => (\n            <div key={i} style={{\n              position: 'absolute',\n              left: '50%',\n              top: i === 0 ? titleTop : '58%',\n              transform: i === 0 ? titleTranslate : 'translate(-50%, 0%)',\n              fontFamily,\n              fontSize: i === 0 ? 164 : 150,\n              fontWeight: 900,\n              color: textColor,\n              whiteSpace: 'nowrap',\n              letterSpacing: -7,\n              textTransform: 'uppercase',\n              filter: titleBlur > 0 ? `blur(${titleBlur}px)` : 'none',\n            }}>\n              {line.toUpperCase()}\n            </div>\n          ))}\n        </div>\n      </div>\n\n      <div style={{\n        position: 'absolute', inset: 0,\n        pointerEvents: 'none',\n        backgroundImage: 'radial-gradient(rgba(255,255,255,0.1) 0.7px, transparent 0.7px)',\n        backgroundSize: '5px 5px',\n      }} />\n    </div>\n  );\n};\n"
