    code: `const LiquidMetalText = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const props = item.props || {};

  const titleText = props.titleText;
  const bodyText = props.bodyText;
  const titleFont = props.titleFont;
  const bodyFont = props.bodyFont;
  const bgColor = props.bgColor;
  const transparentBackground = props.transparentBackground;
  const blobColor1 = props.blobColor1;
  const blobColor2 = props.blobColor2;
  const blobColor3 = props.blobColor3;

  const backgroundFill = transparentBackground ? 'transparent' : bgColor;

  const safeFps = fps || 30;
  
  const titleOpacity = interpolate(frame, [10, 30], [0, 1], { extrapolateRight: 'clamp' });
  const titleSpring = spring({ frame: Math.max(0, frame - 10), fps: safeFps, config: { damping: 16 } });
  const titleY = interpolate(titleSpring, [0, 1], [40, 0]);

  const bodyOpacity = interpolate(frame, [25, 45], [0, 1], { extrapolateRight: 'clamp' });
  const bodySpring = spring({ frame: Math.max(0, frame - 25), fps: safeFps, config: { damping: 16 } });
  const bodyY = interpolate(bodySpring, [0, 1], [40, 0]);

  const t = frame / (durationInFrames || 150);

  const cx1 = 1920 * (0.4 + 0.15 * Math.sin(t * Math.PI * 2));
  const cy1 = 1080 * (0.3 + 0.15 * Math.cos(t * Math.PI * 2));
  
  const cx2 = 1920 * (0.7 + 0.1 * Math.cos(t * Math.PI * 2));
  const cy2 = 1080 * (0.6 + 0.1 * Math.sin(t * Math.PI * 2));

  const cx3 = 1920 * (0.3 + 0.2 * Math.sin(t * Math.PI * 4));
  const cy3 = 1080 * (0.8 + 0.1 * Math.cos(t * Math.PI * 2));

  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor: backgroundFill,
    overflow: 'hidden'
  };

  const svgStyle = {
    position: 'absolute',
    inset: 0,
    width: '100%',
    height: '100%'
  };

  const titleStyle = {
    position: 'absolute',
    top: '20%',
    left: '8%',
    width: '75%',
    opacity: titleOpacity,
    transform: \`translateY(\${titleY}px)\`,
    fontFamily: titleFont,
    fontSize: '96px',
    fontWeight: 700,
    fontStyle: 'italic',
    color: '#FFFFFF',
    lineHeight: 1.15,
    letterSpacing: '-0.02em',
    textShadow: '0 4px 16px rgba(0,0,0,0.25)'
  };

  const bodyStyle = {
    position: 'absolute',
    top: '55%',
    left: '45%',
    width: '45%',
    opacity: bodyOpacity,
    transform: \`translateY(\${bodyY}px)\`,
    fontFamily: bodyFont,
    fontSize: '30px',
    fontWeight: 400,
    color: 'rgba(255, 255, 255, 0.9)',
    lineHeight: 1.6,
    textShadow: '0 2px 8px rgba(0,0,0,0.2)'
  };

  return (
    <div style={rootStyle}>
      {!transparentBackground && (
        <svg style={svgStyle}>
          <defs>
            <filter id="liquidBlur" x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="180" />
            </filter>
          </defs>
          <g filter="url(#liquidBlur)">
            <circle cx={cx1} cy={cy1} r="900" fill={blobColor1} />
            <circle cx={cx2} cy={cy2} r="1000" fill={blobColor2} />
            <circle cx={cx3} cy={cy3} r="800" fill={blobColor3} />
          </g>
        </svg>
      )}

      <div style={titleStyle}>
        {titleText}
      </div>

      <div style={bodyStyle}>
        {bodyText}
      </div>
    </div>
  );
};`
