    thumb: "/thumbnails/4a1c2bc0-9798-4ef4-bbf9-0517cc5ca787.jpg",
    code: "const TheCollective = ({item}) => {\n  const frame = useCurrentFrame();\n  const {fps} = useVideoConfig();\n  \n  const props = item.props || {};\n  const titleText = props.titleText;\n  const m1Name = props.m1Name;\n  const m1Role = props.m1Role;\n  const m1Image = props.m1Image;\n  const m2Name = props.m2Name;\n  const m2Role = props.m2Role;\n  const m2Image = props.m2Image;\n  const m3Name = props.m3Name;\n  const m3Role = props.m3Role;\n  const m3Image = props.m3Image;\n  const fontFamily = props.fontFamily;\n  const bgColor = props.bgColor;\n  const transparentBackground = props.transparentBackground;\n\n  const safeFps = fps || 30;\n  const safeSpring = (delay = 0, config = { damping: 15 }) => {\n    return spring({ frame: Math.max(0, frame - delay), fps: safeFps, config });\n  };\n\n  const titleY = interpolate(frame, [0, 20], [50, 0], { extrapolateRight: 'clamp' });\n  const titleOpacity = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: 'clamp' });\n\n  const m1Scale = safeSpring(24, { damping: 15 });\n  const m1Opacity = interpolate(frame, [24, 34], [0, 1], { extrapolateRight: 'clamp' });\n\n  const m2Scale = safeSpring(54, { damping: 15 });\n  const m2Opacity = interpolate(frame, [54, 64], [0, 1], { extrapolateRight: 'clamp' });\n\n  const m3Scale = safeSpring(84, { damping: 15 });\n  const m3Opacity = interpolate(frame, [84, 94], [0, 1], { extrapolateRight: 'clamp' });\n\n  const b1x = 1920 / 2 + Math.sin(frame / 40) * 600;\n  const b1y = 1080 / 2 + Math.cos(frame / 45) * 300;\n  const b2x = 1920 / 4 + Math.cos(frame / 30) * 400;\n  const b2y = 1080 / 3 + Math.sin(frame / 35) * 400;\n  const b3x = 1920 * 0.75 + Math.sin(frame / 50) * 500;\n  const b3y = 1080 * 0.75 + Math.cos(frame / 30) * 400;\n  const b4x = 1920 / 2 + Math.cos(frame / 60) * 400;\n  const b4y = 1080 / 2 + Math.sin(frame / 40) * 500;\n\n  const backgroundColor = transparentBackground ? 'transparent' : bgColor;\n\n  const rootStyle = {\n    position: 'absolute',\n    inset: 0,\n    backgroundColor,\n    fontFamily,\n    color: 'white',\n    overflow: 'hidden'\n  };\n\n  const titleStyle = {\n    position: 'absolute',\n    top: 150,\n    left: 150,\n    opacity: titleOpacity,\n    transform: `translateY(${titleY}px)`,\n    zIndex: 1\n  };\n\n  const titleHeadingStyle = {\n    fontSize: 64,\n    fontStyle: 'italic',\n    fontWeight: 900,\n    margin: 0,\n    textShadow: '0 4px 20px rgba(0,0,0,0.3)'\n  };\n\n  const membersContainerStyle = {\n    position: 'absolute',\n    top: 380,\n    left: 0,\n    width: '100%',\n    display: 'flex',\n    justifyContent: 'center',\n    gap: 120,\n    zIndex: 1\n  };\n\n  const memberContainerStyle = {\n    display: 'flex',\n    flexDirection: 'column',\n    alignItems: 'center'\n  };\n\n  const circleStyle = {\n    width: 320,\n    height: 320,\n    borderRadius: '50%',\n    border: '4px solid rgba(255,255,255,0.8)',\n    overflow: 'hidden',\n    display: 'flex',\n    justifyContent: 'center',\n    alignItems: 'center',\n    backgroundColor: 'rgba(255,255,255,0.05)',\n    boxShadow: '0 10px 30px rgba(0,0,0,0.4)'\n  };\n\n  const imageStyle = {\n    width: '100%',\n    height: '100%',\n    objectFit: 'cover'\n  };\n\n  const nameStyle = {\n    fontSize: 40,\n    fontStyle: 'italic',\n    fontWeight: 800,\n    margin: '40px 0 10px 0',\n    textAlign: 'center',\n    textShadow: '0 4px 15px rgba(0,0,0,0.3)'\n  };\n\n  const roleStyle = {\n    fontSize: 22,\n    fontWeight: 400,\n    margin: 0,\n    opacity: 0.9,\n    textAlign: 'center',\n    textShadow: '0 4px 15px rgba(0,0,0,0.3)'\n  };\n\n  const member1Transform = `scale(${m1Scale})`;\n  const member2Transform = `scale(${m2Scale})`;\n  const member3Transform = `scale(${m3Scale})`;\n\n  const bgContainerStyle = {\n    position: 'absolute',\n    inset: 0,\n    zIndex: 0,\n    overflow: 'hidden',\n    backgroundColor: bgColor\n  };\n\n  const renderBlob = (color, x, y, size) => {\n    const left = x - size / 2;\n    const top = y - size / 2;\n    const background = `radial-gradient(circle, ${color} 0%, transparent 60%)`;\n    return (\n      <div style={{\n        position: 'absolute',\n        left,\n        top,\n        width: size,\n        height: size,\n        background,\n        borderRadius: '50%',\n        opacity: 0.8\n      }} />\n    );\n  };\n\n  return (\n    <div style={rootStyle}>\n      {!transparentBackground && (\n        <div style={bgContainerStyle}>\n          {renderBlob('#0079cc', b1x, b1y, 1200)}\n          {renderBlob('#006a82', b2x, b2y, 1400)}\n          {renderBlob('#00a2a2', b3x, b3y, 1500)}\n          {renderBlob('#005b7d', b4x, b4y, 1600)}\n        </div>\n      )}\n\n      <div style={titleStyle}>\n        <h1 style={titleHeadingStyle}>{titleText}</h1>\n      </div>\n\n      <div style={membersContainerStyle}>\n        <div style={{ ...memberContainerStyle, transform: member1Transform, opacity: m1Opacity }}>\n          <div style={circleStyle}>\n            {m1Image ? <Img src={m1Image} style={imageStyle} /> : null}\n          </div>\n          <h2 style={nameStyle}>{m1Name}</h2>\n          <p style={roleStyle}>{m1Role}</p>\n        </div>\n\n        <div style={{ ...memberContainerStyle, transform: member2Transform, opacity: m2Opacity }}>\n          <div style={circleStyle}>\n            {m2Image ? <Img src={m2Image} style={imageStyle} /> : null}\n          </div>\n          <h2 style={nameStyle}>{m2Name}</h2>\n          <p style={roleStyle}>{m2Role}</p>\n        </div>\n\n        <div style={{ ...memberContainerStyle, transform: member3Transform, opacity: m3Opacity }}>\n          <div style={circleStyle}>\n            {m3Image ? <Img src={m3Image} style={imageStyle} /> : null}\n          </div>\n          <h2 style={nameStyle}>{m3Name}</h2>\n          <p style={roleStyle}>{m3Role}</p>\n        </div>\n      </div>\n    </div>\n  );\n};"
