    code: "const LowerThirdCR = ({ item }) => {\n  const frame = useCurrentFrame();\n  const { fps } = useVideoConfig();\n\n  const props = item.props || {};\n  const mainText = props.mainText;\n  const subText = props.subText;\n  const blueBallColor = props.blueBallColor;\n  const redBallColor = props.redBallColor;\n  const bgColor = props.bgColor;\n  const mainColor = props.mainColor;\n  const subColor = props.subColor;\n  const lineColor = props.lineColor;\n\n  const DESIGN_WIDTH = 900;\n  const DESIGN_HEIGHT = 120;\n  const scale = Math.min(\n    (item?.width || DESIGN_WIDTH) / DESIGN_WIDTH,\n    (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT\n  );\n\n  const easeOut = Easing.out(Easing.cubic);\n\n  const BALL = 16;\n  const BG_LEFT = 38;\n  const MAIN_FULL_W = Math.round(mainText.length * 26) + 40;\n  const SUB_FULL_W = Math.round(subText.length * 13) + 24;\n\n  const BG_START = 18;\n  const BG_END = 70;\n\n  const MAIN_TOP = 14;\n  const MAIN_H = 40;\n  const LINE_TOP = MAIN_TOP + MAIN_H;\n  const SUB_TOP = LINE_TOP + 1;\n  const SUB_H = 34;\n\n  const bgProgress = interpolate(frame, [BG_START, BG_END], [0, 1], {\n    easing: easeOut, extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  });\n  const mainBgW = bgProgress * MAIN_FULL_W;\n\n  const mainMaskStop = interpolate(bgProgress, [0, 1], [50, 100], {\n    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  });\n  const mainMask = 'linear-gradient(to right, black 0%, black ' + mainMaskStop + '%, transparent 100%)';\n\n  const mainLen = Math.round(interpolate(frame, [22, 78], [0, mainText.length], {\n    easing: easeOut, extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  }));\n  const displayedMain = mainText.slice(0, mainLen);\n\n  const lineW = interpolate(frame, [BG_START + 14, BG_END + 4], [0, MAIN_FULL_W - 8], {\n    easing: easeOut, extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  });\n\n  const subProgress = interpolate(frame, [52, 98], [0, 1], {\n    easing: easeOut, extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  });\n  const subBgW = subProgress * SUB_FULL_W;\n  const subMaskStop = interpolate(subProgress, [0, 1], [50, 100], {\n    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  });\n  const subMask = 'linear-gradient(to right, black 0%, black ' + subMaskStop + '%, transparent 100%)';\n  const displayedSub = subText.slice(0, Math.round(subProgress * subText.length));\n\n  const blueBallX = BG_LEFT + mainBgW - 74;\n  const blueBallY = MAIN_TOP + MAIN_H - BALL;\n  const redBallX = BG_LEFT + mainBgW - 18;\n  const redBallY = MAIN_TOP - 10;\n\n  const fadeIn = interpolate(bgProgress, [0, 0.1], [0, 1], {\n    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  });\n  const blueFadeOut = interpolate(bgProgress, [0.7, 1.0], [1, 0], {\n    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  });\n  const redFadeOut = interpolate(bgProgress, [0.7, 1.0], [1, 0], {\n    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  });\n  const blueBallOpacity = fadeIn * blueFadeOut;\n  const redBallOpacity = fadeIn * redFadeOut;\n\n  const rootStyle = {\n    position: 'absolute', top: 0, left: 0,\n    width: DESIGN_WIDTH, height: DESIGN_HEIGHT,\n    transform: 'scale(' + scale + ')',\n    transformOrigin: 'top left',\n    backgroundColor: 'transparent',\n    fontFamily: 'Roboto, sans-serif',\n    overflow: 'visible',\n  };\n\n  return (\n    <div style={rootStyle}>\n      {mainBgW > 1 && (\n        <div style={{\n          position: 'absolute', top: MAIN_TOP, left: BG_LEFT,\n          width: mainBgW, height: MAIN_H,\n          backgroundColor: bgColor,\n          WebkitMaskImage: mainMask, maskImage: mainMask,\n          display: 'flex', alignItems: 'center',\n          paddingLeft: 10, boxSizing: 'border-box', overflow: 'hidden',\n        }}>\n          <span style={{\n            fontSize: 32, fontWeight: '700', color: mainColor,\n            whiteSpace: 'nowrap', letterSpacing: 0.5, lineHeight: 1,\n          }}>{displayedMain}</span>\n        </div>\n      )}\n      {lineW > 1 && (\n        <div style={{\n          position: 'absolute', top: LINE_TOP, left: 48,\n          height: 1.5, width: lineW,\n          background: 'linear-gradient(to right, ' + lineColor + ' 0%, rgba(153,153,153,0) 100%)',\n        }} />\n      )}\n      {subBgW > 1 && (\n        <div style={{\n          position: 'absolute', top: SUB_TOP, left: BG_LEFT,\n          width: subBgW, height: SUB_H,\n          backgroundColor: bgColor,\n          WebkitMaskImage: subMask, maskImage: subMask,\n          display: 'flex', alignItems: 'center',\n          paddingLeft: 10, boxSizing: 'border-box', overflow: 'hidden',\n        }}>\n          <span style={{\n            fontSize: 20, fontStyle: 'italic', color: subColor,\n            whiteSpace: 'nowrap', lineHeight: 1,\n          }}>{displayedSub}</span>\n        </div>\n      )}\n      <div style={{\n        position: 'absolute', top: blueBallY, left: blueBallX,\n        width: BALL, height: BALL, borderRadius: '50%',\n        backgroundColor: blueBallColor, opacity: blueBallOpacity, zIndex: 10,\n      }} />\n      <div style={{\n        position: 'absolute', top: redBallY, left: redBallX,\n        width: BALL, height: BALL, borderRadius: '50%',\n        backgroundColor: redBallColor, opacity: redBallOpacity, zIndex: 10,\n      }} />\n    </div>\n  );\n};"
