    code: "const SubtitleOverlay = ({item}) => {\n  const frame = useCurrentFrame();\n  const {fps} = useVideoConfig();\n\n  const props = item.props || {};\n  const line1Text = props.line1Text;\n  const line2TextNormal = props.line2TextNormal;\n  const line2TextHighlight = props.line2TextHighlight;\n  const fontFamily = props.fontFamily;\n  const primaryColor = props.primaryColor;\n  const highlightColor = props.highlightColor;\n  const gradientColor = props.gradientColor;\n  const slideDuration = props.slideDuration;\n  const revealAt = Math.min(props.revealAt, slideDuration - 1);\n  const wordDelay = props.wordDelay;\n  const wordDuration = slideDuration;\n\n  const DESIGN_WIDTH = 1920;\n  const DESIGN_HEIGHT = 1080;\n  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);\n\n  const gradientProgress = interpolate(frame, [0, slideDuration], [0, 1], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n    easing: Easing.bezier(0.95, 0, 0.05, 1)\n  });\n  // translate3d \u66FF\u4EE3 translateY\uFF0C\u6E10\u53D8\u5C42\u8D70 GPU \u5408\u6210\uFF0C\u907F\u514D\u5149\u6805\u5316\u6296\u52A8\n  const gradientY = interpolate(gradientProgress, [0, 1], [200, 0]);\n  const gradientOpacity = interpolate(frame, [revealAt, slideDuration], [0, 1], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n    easing: Easing.out(Easing.quad)\n  });\n\n  const line1Words = (line1Text || '').split(' ');\n  const line2Words = (line2TextNormal || '').trim().split(' ').filter(Boolean);\n  const highlightWord = line2TextHighlight || '';\n  const wordInterval = Math.round(slideDuration * 0.2);\n\n  const getWordProgress = (wordIndex) => {\n    const localFrame = Math.max(0, frame - wordDelay - wordIndex * wordInterval);\n    return interpolate(localFrame, [0, wordDuration], [0, 1], {\n      extrapolateLeft: 'clamp',\n      extrapolateRight: 'clamp',\n      easing: Easing.bezier(0.22, 1, 0.36, 1)\n    });\n  };\n\n  const wordStyle = (wordIndex) => {\n    const p = getWordProgress(wordIndex);\n    const yOffset = interpolate(p, [0, 1], [22, 0]);\n    return {\n      display: 'inline-block',\n      opacity: p,\n      // translate3d \u66FF\u4EE3 translateY\uFF0C\u5F3A\u5236\u6BCF\u4E2A\u8BCD\u63D0\u5347\u4E3A\u72EC\u7ACB GPU \u5408\u6210\u5C42\n      transform: `translate3d(0, ${yOffset}px, 0)`,\n      willChange: 'transform',\n      marginRight: '0.28em',\n      transformOrigin: 'bottom center'\n    };\n  };\n\n  return (\n    <div style={{\n      position: 'absolute', top: 0, left: 0,\n      width: DESIGN_WIDTH, height: DESIGN_HEIGHT,\n      // translate3d(0,0,0) \u524D\u7F6E scale\uFF0C\u6839\u5BB9\u5668\u5F3A\u5236 GPU \u5408\u6210\u5C42\n      transform: `translate3d(0, 0, 0) scale(${scale})`,\n      transformOrigin: 'top left',\n      willChange: 'transform',\n      backgroundColor: 'transparent',\n      overflow: 'hidden'\n    }}>\n      {/* \u6E10\u53D8\u5C42\uFF1Atranslate3d \u66FF\u4EE3 translateY\uFF0C\u767E\u5206\u6BD4\u5355\u4F4D\u4FDD\u6301\u4E0D\u53D8 */}\n      <div style={{\n        position: 'absolute',\n        bottom: 0, left: 0,\n        width: '100%', height: '50%',\n        background: `linear-gradient(to top, ${gradientColor}, transparent)`,\n        transform: `translate3d(0, ${gradientY}%, 0)`,\n        willChange: 'transform',\n        opacity: gradientOpacity,\n        zIndex: 1\n      }} />\n      <div style={{\n        position: 'absolute',\n        bottom: '12%',\n        left: 0, right: 0,\n        fontFamily: fontFamily,\n        fontSize: '115px',\n        fontWeight: 400,\n        color: primaryColor,\n        lineHeight: 1.15,\n        display: 'flex',\n        flexDirection: 'column',\n        alignItems: 'center',\n        gap: '8px',\n        textShadow: '0px 8px 24px rgba(0,0,0,0.4)',\n        zIndex: 10\n      }}>\n        <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', alignItems: 'baseline' }}>\n          {line1Words.map((word, i) => (\n            <span key={i} style={wordStyle(i)}>{word}</span>\n          ))}\n        </div>\n        <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', alignItems: 'baseline' }}>\n          {line2Words.map((word, i) => (\n            <span key={i} style={wordStyle(line1Words.length + i)}>{word}</span>\n          ))}\n          <span style={{ ...wordStyle(line1Words.length + line2Words.length), color: highlightColor }}>\n            {highlightWord}\n          </span>\n        </div>\n      </div>\n    </div>\n  );\n};"
