    code: "const NameCardLowerThird = ({item}) => {\n  const frame = useCurrentFrame();\nconst DESIGN_WIDTH = 1920;\nconst DESIGN_HEIGHT = 1080;\nconst scale = Math.min(\n  (item?.width || DESIGN_WIDTH) / DESIGN_WIDTH,\n  (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT\n);\n\n  const props = item.props || {};\n  const nameText = props.nameText;\n  const roleText = props.roleText;\n  const handleText = props.handleText;\n  const accentColor = props.accentColor;\n  const fontFamily = props.fontFamily;\n  const backgroundColor = props.backgroundColor;\n\n  const ITEM_W = item?.width || 1920;\n  const ITEM_H = item?.height || 1080;\n\n  const CARD_H = Math.round(ITEM_H * 0.10);\n  const CARD_LEFT = Math.round(ITEM_W * 0.06);\n  const CARD_TOP_FINAL = Math.round(ITEM_H * 0.74);\n\n  const padH = Math.round(ITEM_W * 0.012);\n  const nameFontSize = Math.round(ITEM_H * 0.032);\n  const roleFontSize = Math.round(ITEM_H * 0.020);\n  const handleFontSize = Math.round(ITEM_H * 0.017);\n  const dividerH = Math.round(ITEM_H * 0.048);\n  const DIVIDER_W = 2;\n\n  const NAME_W = Math.round(ITEM_W * 0.115);\n  const RIGHT_CONTENT_W = Math.round(ITEM_W * 0.22);\n  const CARD_W = NAME_W + DIVIDER_W + RIGHT_CONTENT_W + padH * 4;\n  const SOFT_PX = 40;\n\n  const cardTop = interpolate(frame, [0, 22], [ITEM_H + 40, CARD_TOP_FINAL], {\n    easing: Easing.out(Easing.cubic),\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp'\n  });\n\n  const cl1 = interpolate(frame, [14, 75], [-SOFT_PX, RIGHT_CONTENT_W + SOFT_PX], {\n    easing: Easing.linear,\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp'\n  });\n\n  const cl2 = interpolate(frame, [52, 105], [-SOFT_PX, RIGHT_CONTENT_W + SOFT_PX], {\n    easing: Easing.linear,\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp'\n  });\n\n  const nameOpacity = interpolate(frame, [6, 26], [0, 1], {\n    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  });\n  const nameY = interpolate(frame, [6, 26], [8, 0], {\n    easing: Easing.out(Easing.quad),\n    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'\n  });\n\n  const curtain = (cl) => ({\n    position: 'absolute',\n    top: -4, bottom: -4, left: 0,\n    width: RIGHT_CONTENT_W + SOFT_PX * 2,\n    background: `linear-gradient(to right, transparent ${cl}px, ${backgroundColor} ${cl + SOFT_PX}px)`,\n    pointerEvents: 'none',\n    zIndex: 2,\n  });\n\n  return (\n    <div style={{\n      position: 'absolute', top: 0, left: 0,\n      width: ITEM_W, height: ITEM_H,\n      backgroundColor: 'transparent', overflow: 'hidden'\n    }}>\n      <div style={{\n        position: 'absolute',\n        top: cardTop, left: CARD_LEFT,\n        width: CARD_W, height: CARD_H,\n        backgroundColor: backgroundColor,\n        borderRadius: Math.round(ITEM_H * 0.012),\n        boxShadow: '0 4px 20px rgba(0,0,0,0.12)',\n        display: 'flex', alignItems: 'center',\n        overflow: 'hidden'\n      }}>\n        <div style={{\n          flexShrink: 0,\n          width: NAME_W,\n          display: 'flex', alignItems: 'center', justifyContent: 'center',\n          paddingLeft: padH, paddingRight: padH,\n          opacity: nameOpacity,\n          transform: `translateY(${nameY}px)`\n        }}>\n          <p style={{\n            fontFamily: fontFamily,\n            fontSize: nameFontSize,\n            fontWeight: 700,\n            color: '#1a1a1a',\n            letterSpacing: '-0.2px',\n            lineHeight: 1,\n            margin: 0,\n            whiteSpace: 'nowrap'\n          }}>{nameText}</p>\n        </div>\n        <div style={{\n          flexShrink: 0,\n          width: DIVIDER_W,\n          height: dividerH,\n          backgroundColor: accentColor,\n          opacity: 0.75\n        }} />\n        <div style={{\n          flexShrink: 0,\n          width: RIGHT_CONTENT_W + padH * 2,\n          display: 'flex', flexDirection: 'column', justifyContent: 'center',\n          paddingLeft: padH, paddingRight: padH\n        }}>\n          <div style={{ position: 'relative', overflow: 'hidden' }}>\n            <p style={{\n              fontFamily: fontFamily,\n              fontSize: roleFontSize,\n              fontWeight: 600,\n              color: '#1a1a1a',\n              lineHeight: 1.25,\n              margin: 0,\n              whiteSpace: 'nowrap',\n              position: 'relative', zIndex: 1\n            }}>{roleText}</p>\n            <div style={curtain(cl1)} />\n          </div>\n          <div style={{\n            position: 'relative', overflow: 'hidden',\n            marginTop: Math.round(ITEM_H * 0.003)\n          }}>\n            <p style={{\n              fontFamily: fontFamily,\n              fontSize: handleFontSize,\n              fontWeight: 400,\n              color: accentColor,\n              lineHeight: 1.25,\n              margin: 0,\n              whiteSpace: 'nowrap',\n              position: 'relative', zIndex: 1\n            }}>{handleText}</p>\n            <div style={curtain(cl2)} />\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n};"
