    code: `const MinimalTeamPresentation = ({item}) => {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();

  const props = item.props || {};
  const titleText = props.titleText;
  const titleFontFamily = props.titleFontFamily;
  const fontFamily = props.fontFamily;
  const textColor = props.textColor;
  const bgColor = props.bgColor;
  const transparentBackground = props.transparentBackground;
  const accentColor1 = props.accentColor1;
  const accentColor2 = props.accentColor2;

  const members = [
    { name: props.member1Name, role: props.member1Role, img: props.member1Img, delay: 30 },
    { name: props.member2Name, role: props.member2Role, img: props.member2Img, delay: 50 },
    { name: props.member3Name, role: props.member3Role, img: props.member3Img, delay: 70 }
  ];

  const backgroundColor = transparentBackground ? 'transparent' : bgColor;

  // --- Easing ---
  const smoothSettle = (t) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    return 1 - Math.pow(1 - t, 3.5);
  };

  // --- Exit ---
  const totalFrames = durationInFrames || 150;
  const exitStart = totalFrames - 25;
  const exitRaw = Math.max(0, Math.min(1, (frame - exitStart) / 25));
  const exitProgress = exitRaw * exitRaw;
  const exitOpacity = 1 - exitProgress;
  const exitScale = 1 - exitProgress * 0.02;

  // --- Blobs: scale 1.04 \u2192 1.0, opacity staggered, gentle sin/cos drift ---
  const blob1FadeRaw = Math.min(1, Math.max(0, frame / 40));
  const blob1Opacity = smoothSettle(blob1FadeRaw) * 0.7;
  const blob2FadeRaw = Math.min(1, Math.max(0, (frame - 8) / 40));
  const blob2Opacity = smoothSettle(blob2FadeRaw) * 0.6;

  const blob1DriftX = Math.sin(frame / 55) * 8;
  const blob1DriftY = Math.cos(frame / 70) * 6;
  const blob2DriftX = Math.sin(frame / 65) * 7;
  const blob2DriftY = Math.cos(frame / 50) * 5;

  // --- Title: starts frame 5, 50 frames ---
  const titleRaw = Math.min(1, Math.max(0, (frame - 5) / 50));
  const titleProgress = smoothSettle(titleRaw);
  const titleOpacity = smoothSettle(Math.min(1, Math.max(0, (frame - 5) / 18)));
  const titleY = (1 - titleProgress) * 60;

  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor,
    overflow: 'hidden',
    fontFamily: fontFamily,
    opacity: exitOpacity,
    transform: \`scale(\${exitScale})\`
  };

  return (
    <div style={rootStyle}>
      {/* Organic Background Blobs \u2014 no linear translate, only drift */}
      <div style={{position: 'absolute', top: -600, right: -800, opacity: blob1Opacity, transform: \`translate(\${blob1DriftX}px, \${blob1DriftY}px)\`}}>
        <svg width="2400" height="2400">
          <defs>
            <radialGradient id="gradPeach" cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor={accentColor2} stopOpacity="0.9" />
              <stop offset="100%" stopColor={accentColor2} stopOpacity="0" />
            </radialGradient>
          </defs>
          <circle cx="1200" cy="1200" r="1200" fill="url(#gradPeach)" />
        </svg>
      </div>

      <div style={{position: 'absolute', bottom: -700, left: -400, opacity: blob2Opacity, transform: \`translate(\${blob2DriftX}px, \${blob2DriftY}px)\`}}>
        <svg width="2000" height="2000">
          <defs>
            <radialGradient id="gradSage" cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor={accentColor1} stopOpacity="0.8" />
              <stop offset="100%" stopColor={accentColor1} stopOpacity="0" />
            </radialGradient>
          </defs>
          <circle cx="1000" cy="1000" r="1000" fill="url(#gradSage)" />
        </svg>
      </div>

      {/* Title */}
      <div style={{
        position: 'absolute',
        top: 180,
        left: 180,
        fontSize: 120,
        fontFamily: titleFontFamily,
        fontStyle: 'italic',
        color: textColor,
        opacity: titleOpacity,
        transform: \`translateY(\${titleY}px)\`,
        letterSpacing: '-0.02em'
      }}>
        {titleText}
      </div>

      {/* Team Members */}
      <div style={{
        position: 'absolute',
        top: 480,
        left: 180,
        right: 180,
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'flex-start'
      }}>
        {members.map((member, i) => {
          const mRaw = Math.min(1, Math.max(0, (frame - member.delay) / 45));
          const mProgress = smoothSettle(mRaw);
          const mOpacity = smoothSettle(Math.min(1, Math.max(0, (frame - member.delay) / 15)));
          return (
            <div key={i} style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'flex-start',
              opacity: mOpacity,
              transform: \`translateY(\${(1 - mProgress) * 50}px)\`,
              width: 280
            }}>
              <div style={{
                width: 280,
                height: 280,
                borderRadius: '50%',
                border: \`2px solid rgba(236,207,229, 0.4)\`,
                backgroundColor: member.img ? 'transparent' : 'rgba(207,203,233, 0.1)',
                overflow: 'hidden',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: '0px 20px 40px rgba(0,0,0,0.02)'
              }}>
                {member.img ? (
                  <Img src={member.img} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                ) : null}
              </div>
              <div style={{
                marginTop: 45,
                fontSize: 40,
                fontFamily: titleFontFamily,
                color: textColor,
                lineHeight: 1.1
              }}>
                {member.name}
              </div>
              <div style={{
                marginTop: 16,
                fontSize: 18,
                fontFamily: fontFamily,
                color: textColor,
                textTransform: 'uppercase',
                letterSpacing: '0.1em',
                opacity: 0.65
              }}>
                {member.role}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};`
