    code: "const LowerThirdNameBar = ({item}) => {\n  const baseFrame = useCurrentFrame();\n  const {fps, durationInFrames} = useVideoConfig();\n\n  const props = item.props || {};\n  const nameText = props.nameText;\n  const subtitleText = props.subtitleText;\n  const color1 = props.color1;\n  const color2 = props.color2;\n  const color3 = props.color3;\n  const transparentBackground = props.transparentBackground;\n\n  const DESIGN_WIDTH = 1920;\n  const DESIGN_HEIGHT = 1080;\n  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);\n\n  const qFrame = Math.floor(baseFrame / 3) * 3;\n\n  const nameLen = nameText ? nameText.length : 0;\n  const TYPE_START = 6;\n  const TYPE_SPEED = 1;\n  const charsToShow = Math.min(nameLen, Math.max(0, Math.floor((qFrame - TYPE_START) / TYPE_SPEED)));\n  const displayedName = nameText ? nameText.substring(0, charsToShow) : '';\n\n  const nameFinishFrame = TYPE_START + nameLen * TYPE_SPEED;\n  const subStartFrame = nameFinishFrame + 4;\n  const subEndFrame = subStartFrame + 12;\n  const subHeight = interpolate(qFrame, [subStartFrame, subEndFrame], [0, 48], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });\n\n  const BAR_HEIGHT = 140;\n  const BAR_DURATION = 9;\n  const yellowStart  = subEndFrame - BAR_DURATION;\n  const magentaStart = yellowStart - 4;\n  const cyanStart    = magentaStart - 6;\n\n  const cyanHeight    = interpolate(qFrame, [cyanStart,    cyanStart    + BAR_DURATION], [0, BAR_HEIGHT], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });\n  const magentaHeight = interpolate(qFrame, [magentaStart, magentaStart + BAR_DURATION], [0, BAR_HEIGHT], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });\n  const yellowHeight  = interpolate(qFrame, [yellowStart,  yellowStart  + BAR_DURATION], [0, BAR_HEIGHT], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });\n\n  const rootStyle = {\n    position: 'absolute', top: 0, left: 0,\n    width: DESIGN_WIDTH, height: DESIGN_HEIGHT,\n    transform: `scale(${scale})`, transformOrigin: 'top left',\n    backgroundColor: transparentBackground ? 'transparent' : '#1a1a1a',\n    overflow: 'hidden'\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={{ position: 'absolute', left: 80, top: 760, width: 1700, height: 200 }}>\n        <div style={{ position: 'absolute', left: 0, top: 8, width: 14, height: BAR_HEIGHT }}>\n          <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: cyanHeight,    backgroundColor: color3, zIndex: 1 }} />\n          <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: magentaHeight, backgroundColor: color2, zIndex: 2 }} />\n          <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: yellowHeight,  backgroundColor: color1, zIndex: 3 }} />\n        </div>\n        <div style={{\n          position: 'absolute', left: 38, top: 0,\n          fontFamily: 'Roboto, sans-serif',\n          fontSize: 88, fontWeight: 'bold', color: '#ffffff',\n          lineHeight: '92px', whiteSpace: 'nowrap', letterSpacing: '0.5px'\n        }}>{displayedName}</div>\n        <div style={{\n          position: 'absolute', left: 40, top: 94,\n          width: 1600, height: subHeight, overflow: 'hidden'\n        }}>\n          <div style={{\n            fontFamily: 'Roboto, sans-serif',\n            fontSize: 34, color: 'rgba(255,255,255,0.85)',\n            lineHeight: '48px', whiteSpace: 'nowrap', fontWeight: 'normal', letterSpacing: '0.4px'\n          }}>{subtitleText}</div>\n        </div>\n      </div>\n    </div>\n  );\n};"
