    code: `const FullscreenTextOverlay = ({item}) => { const frame = useCurrentFrame(); const {fps} = useVideoConfig(); const props = item.props || {}; const line1Text = props.line1Text; const line2PreText = props.line2PreText; const highlightedWords = props.highlightedWords; const highlightColor = props.highlightColor; const textColor = props.textColor; const bgColor = props.bgColor; const fontFamily = props.fontFamily; const DESIGN_WIDTH = 1920; const DESIGN_HEIGHT = 1080; const scale = Math.min((item && item.width ? item.width : DESIGN_WIDTH) / DESIGN_WIDTH, (item && item.height ? item.height : DESIGN_HEIGHT) / DESIGN_HEIGHT); const safeFps = fps || 30; const STAGGER = 4; const line1Words = String(line1Text).split(' ').filter(w => w.length > 0); const line2PreWords = String(line2PreText).split(' ').filter(w => w.length > 0); const highWords = String(highlightedWords).split(' ').filter(w => w.length > 0); const totalLine1 = line1Words.length; const totalLine2Pre = line2PreWords.length; const getWordAnim = (index) => { const delay = index * STAGGER; const elapsed = Math.max(0, frame - delay); const t = Math.min(elapsed / 12, 1); const eased = t * (2 - t); const spr = spring({ frame: elapsed, fps: safeFps, config: { damping: 40, stiffness: 140, mass: 1 } }); const y = interpolate(spr, [0, 1], [22, 0]); return { opacity: eased, transform: 'translateY(' + y + 'px)', display: 'inline-block' }; }; const hlStart = (totalLine1 + totalLine2Pre) * STAGGER; const hlDuration = 30; const ht = Math.min(Math.max((frame - hlStart) / hlDuration, 0), 1); const hlReveal = ht * ht; const revealPct = (hlReveal * 100).toFixed(3); const maskVal = 'linear-gradient(to right, black ' + revealPct + '%, transparent ' + revealPct + '%)'; const nH = 80; const nV = 15; const stepH = 100 / nH; const stepV = 100 / nV; const ampH = 2.2; const ampV = 0.4; const noiseH = (seed) => (random(seed) - 0.5) * ampH + (random(seed + 0.37) - 0.5) * ampH * 0.35; const noiseV = (seed) => (random(seed) - 0.5) * ampV + (random(seed + 0.37) - 0.5) * ampV * 0.35; const topPts = Array.from({length: nH + 1}, (_, i) => { const x = i * stepH; const y = noiseH(i * 7 + 1); return x.toFixed(2) + ',' + y.toFixed(2); }).join(' L '); const rightPts = Array.from({length: nV + 1}, (_, i) => { const y = i * stepV; const x = 100 + noiseV(nH + i * 13 + 2); return x.toFixed(2) + ',' + y.toFixed(2); }).join(' L '); const botPts = Array.from({length: nH + 1}, (_, i) => { const x = 100 - i * stepH; const y = 100 + noiseH(2 * nH + i * 7 + 3); return x.toFixed(2) + ',' + y.toFixed(2); }).join(' L '); const leftPts = Array.from({length: nV + 1}, (_, i) => { const y = 100 - i * stepV; const x = noiseV(3 * nH + i * 13 + 4); return x.toFixed(2) + ',' + y.toFixed(2); }).join(' L '); const pathD = 'M 0,0 L ' + topPts + ' L ' + rightPts + ' L ' + botPts + ' L ' + leftPts + ' Z'; const WORD_GAP = '0.28em'; const rootStyle = { position: 'absolute', top: 0, left: 0, width: DESIGN_WIDTH, height: DESIGN_HEIGHT, transform: 'scale(' + scale + ')', transformOrigin: 'top left', backgroundColor: bgColor, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', fontFamily: fontFamily, fontWeight: 800, fontSize: '72px', color: textColor, padding: '0 100px', boxSizing: 'border-box' }; const lineContainerStyle = { textAlign: 'center', lineHeight: 1.25, maxWidth: '100%', whiteSpace: 'nowrap', display: 'flex', flexDirection: 'row', flexWrap: 'nowrap', justifyContent: 'center', alignItems: 'baseline', gap: WORD_GAP }; const line2ContainerStyle = { textAlign: 'center', lineHeight: 1.25, maxWidth: '100%', marginTop: '0.32em', whiteSpace: 'nowrap', display: 'flex', flexDirection: 'row', flexWrap: 'nowrap', justifyContent: 'center', alignItems: 'baseline', gap: WORD_GAP }; const hlWrapStyle = { position: 'relative', display: 'inline-flex', flexDirection: 'row', alignItems: 'baseline', gap: WORD_GAP, paddingLeft: '0.18em', paddingRight: '0.18em' }; const hlSvgContainerStyle = { position: 'absolute', top: '-6px', left: '-4px', right: '-4px', bottom: '-6px', zIndex: 0, WebkitMaskImage: maskVal, maskImage: maskVal }; const hlSvgStyle = { width: '100%', height: '100%', display: 'block' }; const l1Items = line1Words.map((w, i) => { return <span key={'l1' + i} style={getWordAnim(i)}>{w}</span>; }); const l2Items = line2PreWords.map((w, i) => { const idx = totalLine1 + i; return <span key={'l2' + i} style={getWordAnim(idx)}>{w}</span>; }); const hiItems = highWords.map((w, i) => { const idx = totalLine1 + totalLine2Pre + i; const anim = getWordAnim(idx); return <span key={'hi' + i} style={{ opacity: anim.opacity, transform: anim.transform, display: 'inline-block', position: 'relative', zIndex: 2 }}>{w}</span>; }); return (<div style={rootStyle}><div style={lineContainerStyle}>{l1Items}</div><div style={line2ContainerStyle}>{l2Items}<span style={hlWrapStyle}><span style={hlSvgContainerStyle}><svg style={hlSvgStyle} viewBox="-3 -3 106 106" preserveAspectRatio="none"><path d={pathD} fill={highlightColor} fillOpacity="0.82"/></svg></span>{hiItems}</span></div></div>); };`
