    code: 'const VictorianHistoryTitle = ({ item }) => {\n  const frame = useCurrentFrame();\n  const { fps, durationInFrames } = useVideoConfig();\n  const safeFps = fps || 30;\n\n  const props = item.props || {};\n  const bgColor = props.bgColor;\n  const transparentBackground = props.transparentBackground;\n  const titleColor = props.titleColor;\n  const accentColor = props.accentColor;\n  const gradeText = props.gradeText;\n  const titleText = props.titleText;\n  const subtitleText = props.subtitleText;\n  const footerText = props.footerText;\n  const fontFamily = props.fontFamily;\n\n  // Timings and Interpolations\n  const fadeOutStart = Math.max(0, durationInFrames - 20);\n  const globalFadeOut = interpolate(frame, [fadeOutStart, durationInFrames - 1], [1, 0], {\n    extrapolateLeft: "clamp",\n    extrapolateRight: "clamp",\n  });\n\n  const bgFade = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });\n\n  const borderScaleRaw = spring({\n    frame: Math.max(0, frame - 5),\n    fps: safeFps,\n    config: { damping: 20, mass: 1, stiffness: 100 },\n  });\n  const borderScale = 0.95 + borderScaleRaw * 0.05;\n  const borderOp = interpolate(frame, [5, 20], [0, 1], { extrapolateRight: "clamp" });\n\n  const badgeY = interpolate(frame, [15, 35], [20, 0], { extrapolateRight: "clamp" });\n  const badgeOp = interpolate(frame, [15, 35], [0, 1], { extrapolateRight: "clamp" });\n\n  const titleY = interpolate(frame, [20, 40], [20, 0], { extrapolateRight: "clamp" });\n  const titleOp = interpolate(frame, [20, 40], [0, 1], { extrapolateRight: "clamp" });\n\n  const subY = interpolate(frame, [25, 45], [20, 0], { extrapolateRight: "clamp" });\n  const subOp = interpolate(frame, [25, 45], [0, 1], { extrapolateRight: "clamp" });\n\n  const footY = interpolate(frame, [30, 50], [20, 0], { extrapolateRight: "clamp" });\n  const footOp = interpolate(frame, [30, 50], [0, 1], { extrapolateRight: "clamp" });\n\n  const rootStyle = {\n    position: "absolute",\n    inset: 0,\n    backgroundColor: transparentBackground ? "transparent" : bgColor,\n    opacity: globalFadeOut * bgFade,\n    fontFamily: fontFamily,\n    color: titleColor,\n    display: "flex",\n    justifyContent: "center",\n    alignItems: "center",\n    overflow: "hidden",\n  };\n\n  const vignetteStyle = {\n    position: "absolute",\n    inset: 0,\n    background: "radial-gradient(circle, rgba(0,0,0,0) 40%, rgba(0,0,0,0.15) 100%)",\n    pointerEvents: "none",\n    opacity: transparentBackground ? 0 : 1,\n  };\n\n  const borderContainerStyle = {\n    position: "absolute",\n    top: 50,\n    bottom: 50,\n    left: 60,\n    right: 60,\n    border: `2px solid ${accentColor}`,\n    padding: 12,\n    opacity: borderOp,\n    transform: `scale(${borderScale})`,\n  };\n\n  const innerBorderStyle = {\n    width: "100%",\n    height: "100%",\n    border: `1px solid ${accentColor}`,\n    position: "relative",\n    boxSizing: "border-box",\n  };\n\n  const CornerFlourish = ({ style, item }) => (\n    <div style={{ position: "absolute", width: 150, height: 150, ...style }}>\n      <svg viewBox="0 0 150 150" width="100%" height="100%">\n        <g stroke={accentColor} fill="none" strokeWidth="1.5" strokeLinecap="round">\n          <path d="M 0,150 C 0,50 50,0 150,0" />\n          <path d="M 15,150 C 15,70 70,15 150,15" />\n          <path d="M 30,150 C 30,90 70,50 110,40 C 130,35 140,45 130,60 C 115,80 90,60 95,45 C 100,35 110,35 115,45" />\n          <path d="M 150,30 C 90,30 50,70 40,110 C 35,130 45,140 60,130 C 80,115 60,90 45,95 C 35,100 35,110 45,115" />\n          <circle cx="20" cy="20" r="2.5" fill={accentColor} />\n          <path d="M 0,0 L 25,0 C 25,25 0,25 0,25 Z" fill={accentColor} stroke="none" />\n        </g>\n      </svg>\n    </div>\n  );\n\n  const contentWrapperStyle = {\n    position: "relative",\n    zIndex: 10,\n    display: "flex",\n    flexDirection: "column",\n    alignItems: "center",\n    textAlign: "center",\n    padding: "0 120px",\n  };\n\n  const badgeStyle = {\n    border: `1px solid ${titleColor}`,\n    padding: "8px 24px",\n    fontSize: 22,\n    letterSpacing: 2,\n    textTransform: "uppercase",\n    marginBottom: 60,\n    opacity: badgeOp,\n    transform: `translateY(${badgeY}px)`,\n  };\n\n  const titleDisplayStyle = {\n    fontSize: 72,\n    fontWeight: 600,\n    lineHeight: 1.15,\n    whiteSpace: "pre-line",\n    marginBottom: 40,\n    opacity: titleOp,\n    transform: `translateY(${titleY}px)`,\n  };\n\n  const subtitleDisplayStyle = {\n    fontSize: 56,\n    fontStyle: "italic",\n    fontWeight: 400,\n    marginBottom: 70,\n    opacity: subOp,\n    transform: `translateY(${subY}px)`,\n  };\n\n  const footerContainerStyle = {\n    display: "flex",\n    flexDirection: "column",\n    alignItems: "center",\n    opacity: footOp,\n    transform: `translateY(${footY}px)`,\n  };\n\n  const dividerStyle = {\n    width: 600,\n    height: 1,\n    backgroundColor: accentColor,\n  };\n\n  const footerTextStyle = {\n    fontSize: 28,\n    letterSpacing: 1,\n    fontWeight: 300,\n    margin: "30px 0",\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={vignetteStyle} />\n      \n      <div style={borderContainerStyle}>\n        <div style={innerBorderStyle}>\n          <CornerFlourish style={{ top: 0, left: 0 }} />\n          <CornerFlourish style={{ top: 0, right: 0, transform: "scaleX(-1)" }} />\n          <CornerFlourish style={{ bottom: 0, left: 0, transform: "scaleY(-1)" }} />\n          <CornerFlourish style={{ bottom: 0, right: 0, transform: "scale(-1, -1)" }} />\n        </div>\n      </div>\n\n      <div style={contentWrapperStyle}>\n        <div style={badgeStyle}>{gradeText}</div>\n        <div style={titleDisplayStyle}>{titleText}</div>\n        <div style={subtitleDisplayStyle}>{subtitleText}</div>\n        \n        <div style={footerContainerStyle}>\n          <div style={dividerStyle} />\n          <div style={footerTextStyle}>{footerText}</div>\n          <div style={dividerStyle} />\n        </div>\n      </div>\n    </div>\n  );\n};'
