    code: "const ReconstructionAnchor = ({item}) => {\n  const frame = useCurrentFrame();\n  const {durationInFrames} = useVideoConfig();\n  const props = item.props || {};\n\n  const bgColor = props.transparentBackground ? 'transparent' : props.bgColor;\n  const textColor = props.textColor;\n  const accentColor = props.accentColor;\n  const titleFont = props.titleFont;\n  const bodyFont = props.bodyFont;\n\n  const parseHex = (hex) => {\n    if (!hex) return [0,0,0];\n    const h = hex.replace('#','');\n    return [parseInt(h.substring(0,2),16)||0, parseInt(h.substring(2,4),16)||0, parseInt(h.substring(4,6),16)||0];\n  };\n  const rgba = (hex, a) => { const [r,g,b] = parseHex(hex); return `rgba(${r},${g},${b},${a})`; };\n\n  const smoothSettle = (t) => t<=0?0:t>=1?1:1-Math.pow(1-t,3.5);\n  const bellCurveLate = (t) => t<=0?0:t>=1?1:t<0.4?0.15*Math.pow(t/0.4,2.5):0.15+0.85*(1-Math.pow(1-(t-0.4)/0.6,2.8));\n  const lineDraw = (t) => t<=0?0:t>=1?1:1-Math.pow(1-t,2.8);\n\n  const total = durationInFrames || 150;\n  const exitRaw = Math.max(0, Math.min(1, (frame-(total-25))/25));\n  const ex = 1 - exitRaw*exitRaw;\n\n  const anim = (delay, dur) => smoothSettle(Math.min(1, Math.max(0, (frame-delay)/dur)));\n  const fadeIn = (delay) => smoothSettle(Math.min(1, Math.max(0, (frame-delay)/15)));\n\n  // Border (delay 0)\n  const borderA = fadeIn(0)*ex;\n\n  // Title (delay 8)\n  const ttA = fadeIn(8)*ex;\n  const ttY = (1-anim(8,45))*30;\n\n  // Subtitle (delay 18)\n  const stA = fadeIn(18)*ex;\n\n  // Quote (delay 22)\n  const qtA = fadeIn(22)*ex;\n  const qtY = (1-anim(22,35))*20;\n\n  // Bullet columns (delay 25)\n  const bullets = [0,1,2,3,4].map(i => fadeIn(25+i*4)*ex);\n\n  // Bar chart (delay 18)\n  const bars = [{l:'Manufacturing',v:35,c:accentColor},{l:'Transport',v:30,c:accentColor},{l:'Energy',v:20,c:accentColor},{l:'Agriculture',v:15,c:accentColor}];\n  const maxV = 35;\n\n  // Name tag (delay 30)\n  const nmA = fadeIn(30)*ex;\n\n  // Footer text (delay 20)\n  const ftA = fadeIn(20)*ex;\n\n  return (\n    <div style={{position:'absolute',inset:0,backgroundColor:bgColor,overflow:'hidden',fontFamily:bodyFont,color:textColor}}>\n      {/* Decorative border */}\n      <div style={{position:'absolute',top:35,left:35,right:35,bottom:35,border:`3px solid ${rgba(textColor,borderA*0.6)}`}}/>\n      <div style={{position:'absolute',top:45,left:45,right:45,bottom:45,border:`1px solid ${rgba(textColor,borderA*0.3)}`}}/>\n\n      {/* Corner dots */}\n      {[[50,50],[50,'auto'],[null,50],['auto','auto']].map((pos,i) => {\n        const style = {position:'absolute',width:8,height:8,borderRadius:'50%',backgroundColor:rgba(textColor,borderA*0.5)};\n        if (i===0) { style.top=pos[0]; style.left=pos[1]; }\n        else if (i===1) { style.top=pos[0]; style.right=50; }\n        else if (i===2) { style.bottom=50; style.left=pos[1]; }\n        else { style.bottom=50; style.right=50; }\n        return <div key={i} style={style}/>;\n      })}\n\n      {/* Title area (top center) */}\n      <div style={{position:'absolute',top:100,left:0,width:'100%',textAlign:'center',transform:`translateY(${ttY}px)`}}>\n        <div style={{fontFamily:titleFont,fontSize:72,fontWeight:'bold',color:rgba(textColor,ttA)}}>\n          Industrial Revolution\n        </div>\n        <div style={{fontFamily:titleFont,fontStyle:'italic',fontSize:28,color:rgba(textColor,stA*0.7),marginTop:12}}>\n          - Technology History -\n        </div>\n      </div>\n\n      {/* Quote (left) */}\n      <div style={{position:'absolute',left:120,top:340,width:500,transform:`translateY(${qtY}px)`}}>\n        <div style={{fontFamily:titleFont,fontSize:42,fontStyle:'italic',color:rgba(textColor,qtA),lineHeight:1.3}}>\n          Did You Know?\n        </div>\n        <div style={{fontSize:22,color:rgba(textColor,qtA*0.7),marginTop:16,lineHeight:1.5}}>\n          The first power station opened in 1882.\n        </div>\n      </div>\n\n      {/* Bullet list (left bottom) */}\n      <div style={{position:'absolute',left:120,top:560,width:450}}>\n        <div style={{fontSize:24,fontWeight:'bold',color:rgba(textColor,bullets[0]),marginBottom:12}}>Solar Grid</div>\n        {['Mechanized manufacturing','Railway transportation','Mass production'].map((b,i) => (\n          <div key={i} style={{fontSize:18,color:rgba(textColor,bullets[i+1]*0.8),marginBottom:8,paddingLeft:16,borderLeft:`2px solid ${rgba(accentColor,bullets[i+1]*0.4)}`}}>\n            {b}\n          </div>\n        ))}\n      </div>\n\n      {/* Bar chart (right) */}\n      <div style={{position:'absolute',right:120,top:320,width:500}}>\n        {bars.map((b,i) => {\n          const bRaw = Math.min(1,Math.max(0,(frame-(18+i*10))/50));\n          const bP = bellCurveLate(bRaw);\n          const bA = fadeIn(18+i*10)*ex;\n          const w = (b.v/maxV)*320;\n          return (\n            <div key={i} style={{display:'flex',alignItems:'center',marginBottom:18,height:40}}>\n              <div style={{width:130,fontSize:18,color:rgba(textColor,bA),textAlign:'right',paddingRight:16,fontWeight:'bold'}}>{b.l}</div>\n              <div style={{height:'100%',width:w*bP,backgroundColor:rgba(b.c,bA*0.8),display:'flex',alignItems:'center',paddingLeft:12}}>\n                <span style={{fontSize:16,fontWeight:'bold',color:rgba('#ffffff',bA > 0.5 ? bA : 0)}}>{b.v}%</span>\n              </div>\n            </div>\n          );\n        })}\n      </div>\n\n      {/* Name tag (bottom left) */}\n      <div style={{position:'absolute',left:120,bottom:90}}>\n        <div style={{fontFamily:titleFont,fontSize:28,color:rgba(textColor,nmA)}}>Walter Hensley</div>\n        <div style={{fontSize:16,fontStyle:'italic',color:rgba(textColor,nmA*0.6),marginTop:4}}>Engineer & Founder</div>\n      </div>\n\n      {/* Footer */}\n      <div style={{position:'absolute',bottom:60,left:0,width:'100%',textAlign:'center'}}>\n        <div style={{fontSize:14,letterSpacing:'0.1em',textTransform:'uppercase',color:rgba(textColor,ftA*0.4)}}>\n          Here is where your presentation begins\n        </div>\n      </div>\n    </div>\n  );\n};"
