    code: "const EditorialTeamGrid = ({item}) => {\n  const frame = useCurrentFrame();\n  const {durationInFrames} = useVideoConfig();\n  const props = item.props || {};\n\n  const titleText = props.titleText;\n  const m1Name = props.m1Name;\n  const m1Role = props.m1Role;\n  const m2Name = props.m2Name;\n  const m2Role = props.m2Role;\n  const m3Name = props.m3Name;\n  const m3Role = props.m3Role;\n\n  const transparentBackground = props.transparentBackground;\n  const bgColor = props.bgColor;\n  const boxColor = props.boxColor;\n  const frameColor = props.frameColor;\n  const textColor = props.textColor;\n  const textSecColor = props.textSecColor;\n  const serifFont = props.serifFont;\n  const sansFont = props.sansFont;\n\n  const backgroundColor = transparentBackground ? 'transparent' : bgColor;\n\n  // --- Easing ---\n  const smoothSettle = (t) => {\n    if (t <= 0) return 0;\n    if (t >= 1) return 1;\n    return 1 - Math.pow(1 - t, 3.5);\n  };\n\n  // --- Exit ---\n  const totalFrames = durationInFrames || 150;\n  const exitStart = totalFrames - 25;\n  const exitRaw = Math.max(0, Math.min(1, (frame - exitStart) / 25));\n  const exitProgress = exitRaw * exitRaw;\n  const exitOpacity = 1 - exitProgress;\n  const exitScale = 1 - exitProgress * 0.02;\n\n  // --- Title: starts frame 5, 50 frames ---\n  const titleRaw = Math.min(1, Math.max(0, (frame - 5) / 50));\n  const titleProgress = smoothSettle(titleRaw);\n  const titleY = (1 - titleProgress) * 50;\n  const titleOpacity = smoothSettle(Math.min(1, Math.max(0, (frame - 5) / 18)));\n\n  // --- Cards: staggered starts at 30, 50, 70 with 45-frame duration ---\n  const cardAnim = (startFrame) => {\n    const raw = Math.min(1, Math.max(0, (frame - startFrame) / 45));\n    const progress = smoothSettle(raw);\n    const opacity = smoothSettle(Math.min(1, Math.max(0, (frame - startFrame) / 15)));\n    return { progress, opacity };\n  };\n\n  const m1Anim = cardAnim(30);\n  const m2Anim = cardAnim(50);\n  const m3Anim = cardAnim(70);\n\n  const rootStyle = {\n    position: 'absolute',\n    inset: 0,\n    backgroundColor,\n    display: 'flex',\n    flexDirection: 'column',\n    padding: '100px 140px',\n    boxSizing: 'border-box',\n    fontFamily: serifFont,\n    color: textColor,\n    opacity: exitOpacity,\n    transform: `scale(${exitScale})`\n  };\n\n  const titleStyle = {\n    fontSize: '72px',\n    fontWeight: '400',\n    marginBottom: '80px',\n    letterSpacing: '-1px',\n    transform: `translateY(${titleY}px)`,\n    opacity: titleOpacity\n  };\n\n  const gridStyle = {\n    display: 'flex',\n    gap: '60px',\n    flex: 1,\n    justifyContent: 'space-between'\n  };\n\n  const Card = ({ name, role, anim, item }) => {\n    const cardY = (1 - anim.progress) * 50;\n    const cardOpacity = anim.opacity;\n    const boxHeight = anim.progress * 100;\n\n    const cardStyle = {\n      flex: 1,\n      display: 'flex',\n      flexDirection: 'column',\n      opacity: cardOpacity,\n      transform: `translateY(${cardY}px)`\n    };\n\n    const portraitContainerStyle = {\n      position: 'relative',\n      width: '100%',\n      height: '520px',\n      marginBottom: '40px',\n      overflow: 'visible'\n    };\n\n    const darkBoxStyle = {\n      position: 'absolute',\n      top: '40px',\n      left: '40px',\n      right: 0,\n      bottom: 0,\n      backgroundColor: boxColor,\n      transformOrigin: 'bottom center',\n      transform: `scaleY(${boxHeight / 100})`\n    };\n\n    const lineFrameStyle = {\n      position: 'absolute',\n      top: 0,\n      left: 0,\n      width: '85%',\n      height: '85%',\n      borderTop: `2px solid ${frameColor}`,\n      borderLeft: `2px solid ${frameColor}`,\n      opacity: anim.progress\n    };\n\n    const lineFrameBottomRightStyle = {\n      position: 'absolute',\n      bottom: '-20px',\n      right: '-20px',\n      width: '40%',\n      height: '30%',\n      borderBottom: `2px solid ${frameColor}`,\n      borderRight: `2px solid ${frameColor}`,\n      opacity: anim.progress\n    };\n\n    const nameStyle = {\n      fontSize: '40px',\n      fontWeight: '600',\n      marginBottom: '16px',\n      lineHeight: '1.2'\n    };\n\n    const roleStyle = {\n      fontFamily: sansFont,\n      fontSize: '24px',\n      fontWeight: '400',\n      color: textSecColor,\n      textTransform: 'uppercase',\n      letterSpacing: '2px',\n      lineHeight: '1.5',\n      whiteSpace: 'normal',\n      overflowWrap: 'break-word'\n    };\n\n    return (\n      <div style={cardStyle}>\n        <div style={portraitContainerStyle}>\n          <div style={darkBoxStyle} />\n          <div style={lineFrameStyle} />\n          <div style={lineFrameBottomRightStyle} />\n        </div>\n        <div style={nameStyle}>{name}</div>\n        <div style={roleStyle}>{role}</div>\n      </div>\n    );\n  };\n\n  return (\n    <div style={rootStyle}>\n      <div style={titleStyle}>{titleText}</div>\n      <div style={gridStyle}>\n        <Card name={m1Name} role={m1Role} anim={m1Anim} />\n        <Card name={m2Name} role={m2Role} anim={m2Anim} />\n        <Card name={m3Name} role={m3Role} anim={m3Anim} />\n      </div>\n    </div>\n  );\n};"
