    thumb: "/thumbnails/32da30ba-83e3-43df-94f6-0f62e996a815.jpg",
    code: "const Timeline = ({item}) => {\n  const frame = useCurrentFrame();\n  const {durationInFrames} = useVideoConfig();\n\n  const props = item.props || {};\n  const bgColor = props.transparentBackground ? 'transparent' : props.bgColor;\n  const textColor = props.textColor;\n  const titleText = props.titleText;\n  const titleFont = props.titleFont;\n  const descFont = props.descFont;\n\n  const m1Year = props.m1Year;\n  const m1Desc = props.m1Desc;\n  const m2Year = props.m2Year;\n  const m2Desc = props.m2Desc;\n  const m3Year = props.m3Year;\n  const m3Desc = props.m3Desc;\n  const m4Year = props.m4Year;\n  const m4Desc = props.m4Desc;\n\n  // --- Easing curves ---\n  const smoothSettle = (t) => {\n    if (t <= 0) return 0;\n    if (t >= 1) return 1;\n    return 1 - Math.pow(1 - t, 3.5);\n  };\n  const lineDraw = (t) => {\n    if (t <= 0) return 0;\n    if (t >= 1) return 1;\n    return 1 - Math.pow(1 - t, 2.8);\n  };\n\n  // --- Exit ---\n  const totalFrames = durationInFrames || 210;\n  const exitStart = totalFrames - 25;\n  const exitRaw = Math.max(0, Math.min(1, (frame - exitStart) / 25));\n  const exitProgress = exitRaw * exitRaw;\n  const exitOpacity = 1 - exitProgress;\n  const exitScale = 1 - exitProgress * 0.02;\n\n  // --- Title: starts frame 5, 50 frames ---\n  const titleRaw = Math.min(1, Math.max(0, (frame - 5) / 50));\n  const titleProgress = smoothSettle(titleRaw);\n  const titleOpacity = smoothSettle(Math.min(1, Math.max(0, (frame - 5) / 18)));\n  const titleY = (1 - titleProgress) * 60;\n\n  // --- Vertical line: starts frame 20, 55 frames ---\n  const lineRaw = Math.min(1, Math.max(0, (frame - 20) / 55));\n  const lineProgress = lineDraw(lineRaw);\n  const lineLength = lineProgress * 540;\n\n  // --- Milestones: staggered from frame 40, every 20 frames apart ---\n  const renderMilestone = (year, desc, index, startFrame, yPos) => {\n    const mRaw = Math.min(1, Math.max(0, (frame - startFrame) / 40));\n    const mProgress = smoothSettle(mRaw);\n    const mOpacity = smoothSettle(Math.min(1, Math.max(0, (frame - startFrame) / 15)));\n    const dotScale = mProgress;\n    const leftX = (1 - mProgress) * -30;\n    const rightX = (1 - mProgress) * 30;\n\n    return (\n      <div key={index} style={{position: 'absolute', top: yPos, left: 0, right: 0, height: 120}}>\n        <div style={{\n          position: 'absolute',\n          left: 750 - 6,\n          top: 55,\n          width: 12,\n          height: 12,\n          borderRadius: '50%',\n          backgroundColor: textColor,\n          transform: `scale(${dotScale})`,\n        }} />\n        <div style={{\n          position: 'absolute',\n          right: 1920 - 710,\n          top: 0,\n          opacity: mOpacity,\n          transform: `translateX(${leftX}px)`,\n          fontFamily: titleFont,\n          fontSize: '96px',\n          color: textColor,\n          letterSpacing: '-2px',\n          lineHeight: '1.1',\n        }}>\n          {year}\n        </div>\n        <div style={{\n          position: 'absolute',\n          left: 790,\n          top: 40,\n          width: 800,\n          opacity: mOpacity,\n          transform: `translateX(${rightX}px)`,\n          fontFamily: descFont,\n          fontSize: '30px',\n          color: textColor,\n          lineHeight: '1.4',\n        }}>\n          {desc}\n        </div>\n      </div>\n    );\n  };\n\n  return (\n    <div style={{\n      position: 'absolute',\n      inset: 0,\n      backgroundColor: bgColor,\n      overflow: 'hidden',\n      opacity: exitOpacity,\n      transform: `scale(${exitScale})`\n    }}>\n      <div style={{\n        position: 'absolute',\n        left: 200,\n        top: 150,\n        opacity: titleOpacity,\n        transform: `translateY(${titleY}px)`,\n        fontFamily: titleFont,\n        fontSize: '72px',\n        color: textColor,\n      }}>\n        {titleText}\n      </div>\n\n      <div style={{\n        position: 'absolute',\n        left: 749,\n        top: 355,\n        width: 2,\n        height: lineLength,\n        backgroundColor: textColor,\n      }} />\n\n      {renderMilestone(m1Year, m1Desc, 1, 40, 300)}\n      {renderMilestone(m2Year, m2Desc, 2, 60, 480)}\n      {renderMilestone(m3Year, m3Desc, 3, 80, 660)}\n      {renderMilestone(m4Year, m4Desc, 4, 100, 840)}\n    </div>\n  );\n};"
