    thumb: "/thumbnails/58b32a8f-8d9e-4521-85d6-277dfb37fd68.jpg",
    code: "const TimelineAnimation = ({ item }) => {\n  const frame = useCurrentFrame();\n  const { width, height } = item;\n  const DESIGN_WIDTH = 1920;\n  const DESIGN_HEIGHT = 1080;\n  const scale = Math.min(\n    (width || DESIGN_WIDTH) / DESIGN_WIDTH,\n    (height || DESIGN_HEIGHT) / DESIGN_HEIGHT\n  );\n\n  const props = item.props || {};\n  const text1 = props.text1;\n  const text2 = props.text2;\n  const text3line1 = props.text3line1;\n  const text3line2 = props.text3line2;\n  const dotColor = props.dotColor;\n  const textColor = props.textColor;\n  const transparentBackground = props.transparentBackground === 'true' || props.transparentBackground === true;\n  const fontFamily = props.fontFamily;\n\n  const easeOut = Easing.out(Easing.cubic);\n\n  const dot1Opacity = interpolate(frame, [0, 30], [0, 1], { extrapolateRight: 'clamp', easing: easeOut });\n  const dot1Blur = interpolate(frame, [0, 30], [12, 0], { extrapolateRight: 'clamp', easing: easeOut });\n  const text1Opacity = interpolate(frame, [8, 33], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n  const text1Y = interpolate(frame, [8, 33], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n  const line1Scale = interpolate(frame, [35, 60], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n\n  const dot2Opacity = interpolate(frame, [60, 90], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n  const dot2Blur = interpolate(frame, [60, 90], [12, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n  const text2Opacity = interpolate(frame, [68, 93], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n  const text2Y = interpolate(frame, [68, 93], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n  const line2Scale = interpolate(frame, [95, 120], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n\n  const dot3Opacity = interpolate(frame, [120, 150], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n  const dot3Blur = interpolate(frame, [120, 150], [12, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n  const text3Opacity = interpolate(frame, [128, 153], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n  const text3Y = interpolate(frame, [128, 153], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: easeOut });\n\n  const DOT_R = 12;\n  const SPACING = 160;\n  const TEXT_LEFT = 56;\n  const FONT_SIZE = 52;\n  const LINE_HEIGHT = 1.3;\n\n  // dot center Y coords (relative to container)\n  const cy1 = 0;\n  const cy2 = SPACING;\n  const cy3 = SPACING * 2;\n\n  const dotEl = (cy, opacity, blur) => (\n    <div style={{\n      position: 'absolute',\n      left: -DOT_R,\n      top: cy - DOT_R,\n      width: DOT_R * 2,\n      height: DOT_R * 2,\n      borderRadius: DOT_R,\n      backgroundColor: dotColor,\n      boxShadow: '0 0 10px rgba(255,255,255,0.7)',\n      opacity,\n      filter: `blur(${blur}px)`\n    }} />\n  );\n\n  const lineEl = (cy, scaleY) => (\n    <div style={{\n      position: 'absolute',\n      left: -1.5,\n      top: cy + DOT_R,\n      width: 3,\n      height: SPACING - DOT_R * 2,\n      backgroundColor: dotColor,\n      borderRadius: 1.5,\n      transformOrigin: 'top center',\n      transform: `scaleY(${scaleY})`\n    }} />\n  );\n\n  // text anchored to dot center: top = cy - half of single line height\n  const singleLineH = FONT_SIZE * LINE_HEIGHT;\n  const textEl = (cy, lines, opacity, ty) => (\n    <div style={{\n      position: 'absolute',\n      left: TEXT_LEFT,\n      top: cy - singleLineH / 2,\n      opacity,\n      transform: `translateY(${ty}px)`,\n      fontSize: FONT_SIZE,\n      fontWeight: 700,\n      lineHeight: LINE_HEIGHT,\n      color: textColor,\n      whiteSpace: 'pre',\n      pointerEvents: 'none'\n    }}>\n      {lines}\n    </div>\n  );\n\n  return (\n    <div style={{\n      position: 'absolute', top: 0, left: 0,\n      width: DESIGN_WIDTH, height: DESIGN_HEIGHT,\n      transform: `scale(${scale})`, transformOrigin: 'top left',\n      backgroundColor: transparentBackground ? 'transparent' : '#000000',\n      fontFamily\n    }}>\n      <div style={{ position: 'absolute', left: 180, top: 380 }}>\n        {dotEl(cy1, dot1Opacity, dot1Blur)}\n        {textEl(cy1, text1, text1Opacity, text1Y)}\n        {lineEl(cy1, line1Scale)}\n\n        {dotEl(cy2, dot2Opacity, dot2Blur)}\n        {textEl(cy2, text2, text2Opacity, text2Y)}\n        {lineEl(cy2, line2Scale)}\n\n        {dotEl(cy3, dot3Opacity, dot3Blur)}\n        {textEl(cy3, <>{text3line1}<br />{text3line2}</>, text3Opacity, text3Y)}\n      </div>\n    </div>\n  );\n};"
