// src/editor/initial.ts
var TEMPLATES = [
  ...afterframe_templates_default,
  ...social_shorts_templates_default,
  ...koubo_scenes_templates_default
];
var pick = (name) => TEMPLATES.find((t3) => t3.name.includes(name)) ?? TEMPLATES[0];
var seedItem = (id, tpl, startFrame) => ({
  id,
  track: "V1",
  startFrame,
  durationInFrames: tpl.durationInFrames,
  kind: "motion-graphic",
  templateId: tpl.id,
  name: tpl.name,
  code: tpl.code,
  props: { ...tpl.props },
  width: tpl.width,
  height: tpl.height
});
var SEED_A = pick("Finance Explainer");
var SEED_B = pick("Dark Tech");
var INITIAL = {
  fps: 30,
  width: 1920,
  height: 1080,
  items: [
    seedItem("seed_1", SEED_A, 0),
    seedItem("seed_2", SEED_B, SEED_A.durationInFrames)
  ],
  selectedId: null
};

